1. use oxc_allocator::Allocator;
2. use oxc_ast::ast::{Argument, CallExpression, Expression};
3. use oxc_ast::visit::walk;
4. use oxc_ast::Visit;
5. use oxc_parser::Parser;
6. use oxc_span::SourceType;
7. use std::path::Path;
8. 
9. /// A collected translation key usage with source location.
10. #[derive(Debug, Clone)]
11. pub struct KeyUsage {
12.     pub key: String,
13.     pub file_path: String,
14.     pub line: u32,
15.     pub column: u32,
16.     pub end_column: u32,
17. }
18. 
19. /// Extracts translation keys from TS/JS source files by finding `t('key')` calls.
20. pub struct KeyCollector {
21.     /// Function names to look for (default: `["t", "$t"]`).
22.     pub function_names: Vec<String>,
23. }
24. 
25. impl Default for KeyCollector {
26.     fn default() -> Self {
27.         Self { function_names: vec!["t".to_string(), "$t".to_string()] }
28.     }
29. }
30. 
31. impl KeyCollector {
32.     #[must_use]
33.     pub fn new() -> Self {
34.         Self::default()
35.     }
36. 
37.     /// Creates a collector with custom function names.
38.     #[must_use]
39.     pub fn with_function_names(names: Vec<String>) -> Self {
40.         Self { function_names: names }
41.     }
42. 
43.     /// Collects translation keys from a source file.
44.     pub fn collect_file(&self, path: &Path) -> Result<Vec<KeyUsage>, String> {
45.         let content = std::fs::read_to_string(path)
46.             .map_err(|e| format!("failed to read {}: {e}", path.display()))?;
47.         let file_path = path.to_string_lossy().to_string();
48.         let source_type = SourceType::from_path(path).unwrap_or_default();
49.         self.collect_source(&content, &file_path, source_type)
50.     }
51. 
52.     /// Collects translation keys from source code string.
53.     pub fn collect_source(
54.         &self,
55.         source: &str,
56.         file_path: &str,
57.         source_type: SourceType,
58.     ) -> Result<Vec<KeyUsage>, String> {
59.         let allocator = Allocator::default();
60.         let ret = Parser::new(&allocator, source, source_type).parse();
61. 
62.         if !ret.errors.is_empty() {
63.             let msg = ret
64.                 .errors
65.                 .iter()
66.                 .map(std::string::ToString::to_string)
67.                 .collect::<Vec<_>>()
68.                 .join(", ");
69.             return Err(format!("parse error in {file_path}: {msg}"));
70.         }
71. 
72.         let mut visitor = KeyVisitor::new(source, file_path, &self.function_names);
73.         visitor.visit_program(&ret.program);
74. 
75.         Ok(visitor.usages)
76.     }
77. }
78. 
79. /// AST visitor that collects translation key usages.
80. struct KeyVisitor<'a> {
81.     source: &'a str,
82.     file_path: &'a str,
83.     function_names: &'a [String],
84.     usages: Vec<KeyUsage>,
85. }
86. 
87. impl<'a> KeyVisitor<'a> {
88.     fn new(source: &'a str, file_path: &'a str, function_names: &'a [String]) -> Self {
89.         Self { source, file_path, function_names, usages: Vec::new() }
90.     }
91. 
92.     fn line_col(&self, offset: u32) -> (u32, u32) {
93.         let bytes = self.source.as_bytes();
94.         let mut line = 1u32;
95.         let mut col = 1u32;
96.         for (i, &b) in bytes.iter().enumerate() {
97.             if i == offset as usize {
98.                 break;
99.             }
100.             if b == b'\n' {
101.                 line += 1;
102.                 col = 1;
103.             } else {
104.                 col += 1;
105.             }
106.         }
107.         (line, col)
108.     }
109. }
110. 
111. impl<'a> Visit<'a> for KeyVisitor<'a> {
112.     fn visit_call_expression(&mut self, call: &CallExpression<'a>) {
113.         // Check if this is t('key') or $t('key')
114.         let callee_name = match &call.callee {
115.             Expression::Identifier(id) => Some(id.name.as_str()),
116.             // Handle member expressions like this.t('key') or i18n.t('key')
117.             Expression::StaticMemberExpression(member) => Some(member.property.name.as_str()),
118.             _ => None,
119.         };
120. 
121.         if let Some(name) = callee_name {
122.             if self.function_names.iter().any(|n| n == name) {
123.                 // Extract the first string argument as the key
124.                 if let Some(Argument::StringLiteral(lit)) = call.arguments.first() {
125.                     let (line, col) = self.line_col(call.span.start);
126.                     let (_, end_col) = self.line_col(call.span.end);
127.                     self.usages.push(KeyUsage {
128.                         key: lit.value.to_string(),
129.                         file_path: self.file_path.to_string(),
130.                         line,
131.                         column: col,
132.                         end_column: end_col,
133.                     });
134.                 }
135.             }
136.         }
137. 
138.         // Continue visiting
139.         walk::walk_call_expression(self, call);
140.     }
141. }
142. 
143. #[cfg(test)]
144. mod tests {
145.     use super::*;
146. 
147.     fn collect(source: &str) -> Vec<KeyUsage> {
148.         let collector = KeyCollector::new();
149.         collector.collect_source(source, "test.ts", SourceType::ts()).unwrap()
150.     }
151. 
152.     #[test]
153.     fn simple_t_call() {
154.         let usages = collect(r"const msg = t('common.greeting');");
155.         assert_eq!(usages.len(), 1);
156.         assert_eq!(usages[0].key, "common.greeting");
157.     }
158. 
159.     #[test]
160.     fn dollar_t_call() {
161.         let usages = collect(r"const msg = $t('nav.home');");
162.         assert_eq!(usages.len(), 1);
163.         assert_eq!(usages[0].key, "nav.home");
164.     }
165. 
166.     #[test]
167.     fn member_expression() {
168.         let usages = collect(r"const msg = i18n.t('common.farewell');");
169.         assert_eq!(usages.len(), 1);
170.         assert_eq!(usages[0].key, "common.farewell");
171.     }
172. 
173.     #[test]
174.     fn multiple_calls() {
175.         let usages = collect(
176.             r"
177. const a = t('key1');
178. const b = t('key2');
179. const c = $t('key3');
180. ",
181.         );
182.         assert_eq!(usages.len(), 3);
183.     }
184. 
185.     #[test]
186.     fn ignores_non_translation_calls() {
187.         let usages = collect(r"console.log('not a key'); foo('also not');");
188.         assert!(usages.is_empty());
189.     }
190. 
191.     #[test]
192.     fn ignores_non_string_arg() {
193.         let usages = collect(r"const msg = t(someVariable);");
194.         assert!(usages.is_empty());
195.     }
196. 
197.     #[test]
198.     fn line_column_tracking() {
199.         let usages = collect("const a = 1;\nconst b = t('key');");
200.         assert_eq!(usages.len(), 1);
201.         assert_eq!(usages[0].line, 2);
202.     }
203. }
204.

