1. //! Documentation extraction from source code using OXC parser.
2. 
3. use ox_jsdoc::decoder::nodes::comment_ast::{LazyJsdocTag, LazyJsdocTagBody};
4. use ox_jsdoc::parser::{
5.     parse_batch_to_bytes as parse_jsdoc_batch_to_bytes, BatchItem as JsdocBatchItem,
6.     ParseOptions as JsdocParseOptions,
7. };
8. use oxc_allocator::Allocator;
9. use oxc_ast::ast::{
10.     BindingPatternKind, Class, Comment, Declaration, ExportDefaultDeclarationKind, Expression,
11.     Function, Statement, TSSignature, TSType, TSTypeName,
12. };
13. use oxc_ast::visit::walk;
14. use oxc_ast::Visit;
15. use oxc_parser::Parser;
16. use oxc_span::{GetSpan, SourceType};
17. use rustc_hash::{FxBuildHasher, FxHashMap, FxHashSet};
18. use serde::{Deserialize, Serialize};
19. use std::path::Path;
20. use thiserror::Error;
21. 
22. /// Result type for extraction operations.
23. pub type ExtractResult<T> = Result<T, ExtractError>;
24. 
25. /// Errors during documentation extraction.
26. #[derive(Debug, Error)]
27. pub enum ExtractError {
28.     /// IO error.
29.     #[error("IO error: {0}")]
30.     Io(#[from] std::io::Error),
31. 
32.     /// Parse error.
33.     #[error("Parse error: {0}")]
34.     Parse(String),
35. 
36.     /// Unsupported file type.
37.     #[error("Unsupported file type: {0}")]
38.     UnsupportedFile(String),
39. }
40. 
41. /// Documentation item extracted from source code.
42. #[derive(Debug, Clone, Serialize, Deserialize)]
43. pub struct DocItem {
44.     /// Item name.
45.     pub name: String,
46.     /// Item kind (function, class, interface, etc.).
47.     pub kind: DocItemKind,
48.     /// Documentation comment (JSDoc).
49.     pub doc: Option<String>,
50.     /// Source file path.
51.     pub source_path: String,
52.     /// Line number in source.
53.     pub line: u32,
54.     /// End line number in source.
55.     pub end_line: u32,
56.     /// Column number in source.
57.     pub column: u32,
58.     /// Raw JSDoc comment content without the outer delimiters.
59.     pub jsdoc: Option<String>,
60.     /// Whether the item is exported.
61.     pub exported: bool,
62.     /// Type signature (if applicable).
63.     pub signature: Option<String>,
64.     /// Parameters (for functions/methods).
65.     pub params: Vec<ParamDoc>,
66.     /// Return type (for functions/methods).
67.     pub return_type: Option<String>,
68.     /// Child items (for classes, modules, etc.).
69.     pub children: Vec<DocItem>,
70.     /// JSDoc tags.
71.     pub tags: Vec<DocTag>,
72. }
73. 
74. /// Parameter documentation.
75. #[derive(Debug, Clone, Serialize, Deserialize)]
76. pub struct ParamDoc {
77.     /// Parameter name.
78.     pub name: String,
79.     /// Parameter type.
80.     pub type_annotation: Option<String>,
81.     /// Whether the parameter is optional.
82.     pub optional: bool,
83.     /// Default value (if any).
84.     pub default_value: Option<String>,
85.     /// Description from JSDoc @param tag.
86.     pub description: Option<String>,
87. }
88. 
89. /// JSDoc tag.
90. #[derive(Debug, Clone, Serialize, Deserialize)]
91. pub struct DocTag {
92.     /// Tag name (e.g., "param", "returns", "example").
93.     pub tag: String,
94.     /// Tag value.
95.     pub value: String,
96.     /// JSDoc type annotation, when the tag has a `{type}` part.
97.     #[serde(default, skip_serializing_if = "Option::is_none")]
98.     pub type_annotation: Option<String>,
99.     /// JSDoc name, when the tag has a name part.
100.     #[serde(default, skip_serializing_if = "Option::is_none")]
101.     pub name: Option<String>,
102.     /// Whether the named part was marked optional.
103.     #[serde(default, skip_serializing_if = "Option::is_none")]
104.     pub optional: Option<bool>,
105.     /// Default value from `[name=value]` syntax.
106.     #[serde(default, skip_serializing_if = "Option::is_none")]
107.     pub default_value: Option<String>,
108.     /// Structured tag description parsed by `ox_jsdoc`.
109.     #[serde(default, skip_serializing_if = "Option::is_none")]
110.     pub description: Option<String>,
111. }
112. 
113. impl DocTag {
114.     fn new(tag: String, value: String) -> Self {
115.         Self {
116.             tag,
117.             value,
118.             type_annotation: None,
119.             name: None,
120.             optional: None,
121.             default_value: None,
122.             description: None,
123.         }
124.     }
125. }
126. 
127. #[derive(Debug, Clone)]
128. struct ParsedParamTag {
129.     name: String,
130.     type_annotation: Option<String>,
131.     optional: bool,
132.     default_value: Option<String>,
133.     description: Option<String>,
134. }
135. 
136. /// Kind of documentation item.
137. #[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
138. #[serde(rename_all = "lowercase")]
139. pub enum DocItemKind {
140.     /// Module or namespace.
141.     Module,
142.     /// Function.
143.     Function,
144.     /// Class.
145.     Class,
146.     /// Interface (TypeScript).
147.     Interface,
148.     /// Type alias.
149.     Type,
150.     /// Enum.
151.     Enum,
152.     /// Variable or constant.
153.     Variable,
154.     /// Class method.
155.     Method,
156.     /// Class property.
157.     Property,
158.     /// Constructor.
159.     Constructor,
160.     /// Getter.
161.     Getter,
162.     /// Setter.
163.     Setter,
164. }
165. 
166. /// Documentation extractor.
167. pub struct DocExtractor {
168.     /// Include private items.
169.     include_private: bool,
170. }
171. 
172. impl DocExtractor {
173.     /// Creates a new documentation extractor.
174.     #[must_use]
175.     pub fn new() -> Self {
176.         Self { include_private: false }
177.     }
178. 
179.     /// Creates a new extractor that includes private items.
180.     #[must_use]
181.     pub fn with_private(include_private: bool) -> Self {
182.         Self { include_private }
183.     }
184. 
185.     /// Extracts documentation from a source file.
186.     pub fn extract_file(&self, path: &Path) -> ExtractResult<Vec<DocItem>> {
187.         let extension = path.extension().and_then(|e| e.to_str()).unwrap_or("");
188. 
189.         match extension {
190.             "ts" | "tsx" | "js" | "jsx" | "mts" | "mjs" | "cts" | "cjs" => self.extract_js_ts(path),
191.             _ => Err(ExtractError::UnsupportedFile(extension.to_string())),
192.         }
193.     }
194. 
195.     /// Extracts documentation from source code string.
196.     pub fn extract_source(
197.         &self,
198.         source: &str,
199.         file_path: &str,
200.         source_type: SourceType,
201.     ) -> ExtractResult<Vec<DocItem>> {
202.         let allocator = Allocator::default();
203.         let ret = Parser::new(&allocator, source, source_type).parse();
204. 
205.         if !ret.errors.is_empty() {
206.             let error_msg = ret
207.                 .errors
208.                 .iter()
209.                 .map(std::string::ToString::to_string)
210.                 .collect::<Vec<_>>()
211.                 .join(", ");
212.             return Err(ExtractError::Parse(error_msg));
213.         }
214. 
215.         let comments: Vec<Comment> = ret.program.comments.iter().copied().collect();
216.         let jsdoc_cache = build_jsdoc_cache(source, &comments);
217. 
218.         let mut visitor = DocVisitor::new(source, file_path, self.include_private, jsdoc_cache);
219.         visitor.visit_program(&ret.program);
220. 
221.         Ok(visitor.items)
222.     }
223. 
224.     /// Extracts documentation from a JavaScript/TypeScript file.
225.     fn extract_js_ts(&self, path: &Path) -> ExtractResult<Vec<DocItem>> {
226.         let content = std::fs::read_to_string(path)?;
227.         let file_path = path.to_string_lossy().to_string();
228.         let source_type = SourceType::from_path(path).unwrap_or_default();
229. 
230.         self.extract_source(&content, &file_path, source_type)
231.     }
232. }
233. 
234. impl Default for DocExtractor {
235.     fn default() -> Self {
236.         Self::new()
237.     }
238. }
239. 
240. /// Pre-parsed JSDoc data for one comment: `(raw, description, tags)`.
241. type ParsedJsdoc = (String, String, Vec<DocTag>);
242. 
243. /// Extract the JSDoc content body from a comment with a single allocation.
244. fn extract_raw_jsdoc(comment: &Comment, source: &str) -> String {
245.     let content = comment.content_span().source_text(source);
246.     let trimmed = content.strip_prefix('*').unwrap_or(content);
247.     trimmed.trim_matches('\n').to_string()
248. }
249. 
250. /// Pre-parse every JSDoc comment in the program with a single batch call so the
251. /// AST visitor can resolve documentation by `attached_to` via a cheap lookup.
252. fn build_jsdoc_cache(source: &str, comments: &[Comment]) -> FxHashMap<u32, ParsedJsdoc> {
253.     let jsdoc_comments: Vec<&Comment> =
254.         comments.iter().filter(|comment| comment.is_jsdoc(source)).collect();
255.     if jsdoc_comments.is_empty() {
256.         return FxHashMap::default();
257.     }
258. 
259.     let items: Vec<JsdocBatchItem<'_>> = jsdoc_comments
260.         .iter()
261.         .map(|comment| JsdocBatchItem {
262.             source_text: comment.span.source_text(source),
263.             base_offset: comment.span.start,
264.         })
265.         .collect();
266. 
267.     let options = JsdocParseOptions { preserve_whitespace: true, ..JsdocParseOptions::default() };
268.     let result = parse_jsdoc_batch_to_bytes(&items, options);
269. 
270.     let failed: FxHashSet<u32> =
271.         result.diagnostics.iter().map(|diagnostic| diagnostic.root_index).collect();
272. 
273.     let mut cache: FxHashMap<u32, ParsedJsdoc> =
274.         FxHashMap::with_capacity_and_hasher(jsdoc_comments.len(), FxBuildHasher);
275. 
276.     if let Ok(source_file) =
277.         ox_jsdoc::decoder::source_file::LazySourceFile::new(&result.binary_bytes)
278.     {
279.         for (index, (comment, root)) in jsdoc_comments.iter().zip(source_file.asts()).enumerate() {
280.             let raw = extract_raw_jsdoc(comment, source);
281.             let (doc, tags) = match root {
282.                 Some(root) if !failed.contains(&(index as u32)) => {
283.                     let doc = root
284.                         .description_text(false)
285.                         .map_or_else(String::new, |description| description.trim().to_string());
286.                     let tags = root.tags().map(DocVisitor::convert_jsdoc_tag).collect();
287.                     (doc, tags)
288.                 }
289.                 _ => DocVisitor::parse_jsdoc_fallback(&raw),
290.             };
291.             cache.insert(comment.attached_to, (raw, doc, tags));
292.         }
293.     } else {
294.         for comment in &jsdoc_comments {
295.             let raw = extract_raw_jsdoc(comment, source);
296.             let (doc, tags) = DocVisitor::parse_jsdoc_fallback(&raw);
297.             cache.insert(comment.attached_to, (raw, doc, tags));
298.         }
299.     }
300. 
301.     cache
302. }
303. 
304. /// AST visitor for extracting documentation.
305. struct DocVisitor<'a> {
306.     source: &'a str,
307.     file_path: &'a str,
308.     include_private: bool,
309.     jsdoc_cache: FxHashMap<u32, ParsedJsdoc>,
310.     line_starts: Vec<usize>,
311.     items: Vec<DocItem>,
312.     /// Track default export
313.     has_default_export: bool,
314. }
315. 
316. impl<'a> DocVisitor<'a> {
317.     fn new(
318.         source: &'a str,
319.         file_path: &'a str,
320.         include_private: bool,
321.         jsdoc_cache: FxHashMap<u32, ParsedJsdoc>,
322.     ) -> Self {
323.         let mut line_starts = vec![0];
324.         line_starts.extend(
325.             source
326.                 .bytes()
327.                 .enumerate()
328.                 .filter_map(|(index, byte)| (byte == b'\n').then_some(index + 1)),
329.         );
330. 
331.         Self {
332.             source,
333.             file_path,
334.             include_private,
335.             jsdoc_cache,
336.             line_starts,
337.             items: Vec::new(),
338.             has_default_export: false,
339.         }
340.     }
341. 
342.     fn slice(&self, start: u32, end: u32) -> String {
343.         self.source[start as usize..end as usize].to_string()
344.     }
345. 
346.     fn line_number(&self, position: u32) -> u32 {
347.         let position = position as usize;
348.         self.line_starts.partition_point(|&start| start <= position) as u32
349.     }
350. 
351.     fn column_number(&self, position: u32) -> u32 {
352.         let position = position as usize;
353.         let line_index = self.line_starts.partition_point(|&start| start <= position);
354.         let line_start = self.line_starts[line_index.saturating_sub(1)];
355.         (position.saturating_sub(line_start)) as u32
356.     }
357. 
358.     fn span_lines(&self, start: u32, end: u32) -> (u32, u32) {
359.         let start_line = self.line_number(start);
360.         let end_position = end.saturating_sub(1).max(start);
361.         let end_line = self.line_number(end_position);
362.         (start_line, end_line)
363.     }
364. 
365.     fn extract_jsdoc(&self, attached_to: u32) -> Option<(String, String, Vec<DocTag>)> {
366.         self.jsdoc_cache.get(&attached_to).cloned()
367.     }
368. 
369.     fn convert_jsdoc_tag(tag: LazyJsdocTag<'_>) -> DocTag {
370.         let tag_name = tag.tag().value().to_string();
371.         let value = Self::format_jsdoc_tag_value(&tag_name, &tag);
372.         let type_annotation = tag
373.             .raw_type()
374.             .map(|raw_type| raw_type.raw().trim().to_string())
375.             .filter(|value| !value.is_empty());
376.         let name =
377.             tag.name().map(|name| name.raw().trim().to_string()).filter(|value| !value.is_empty());
378.         let optional = name.as_ref().map(|_| tag.optional());
379.         let default_value = tag.default_value().map(str::trim).filter(|value| !value.is_empty());
380.         let description =
381.             Self::format_structured_tag_description(&tag_name, &tag, type_annotation.as_deref());
382. 
383.         DocTag {
384.             tag: tag_name,
385.             value,
386.             type_annotation,
387.             name,
388.             optional,
389.             default_value: default_value.map(str::to_string),
390.             description,
391.         }
392.     }
393. 
394.     fn format_structured_tag_description(
395.         tag_name: &str,
396.         tag: &LazyJsdocTag<'_>,
397.         type_annotation: Option<&str>,
398.     ) -> Option<String> {
399.         if matches!(tag_name, "returns" | "return") {
400.             let raw_body = tag.raw_body().map(str::trim).filter(|value| !value.is_empty())?;
401.             let without_type = type_annotation
402.                 .and_then(|type_annotation| {
403.                     raw_body.strip_prefix(&format!("{{{type_annotation}}}")).map(str::trim_start)
404.                 })
405.                 .unwrap_or(raw_body);
406.             return Self::clean_tag_description(without_type);
407.         }
408. 
409.         tag.description().and_then(Self::clean_tag_description)
410.     }
411. 
412.     fn format_jsdoc_tag_value(tag_name: &str, tag: &LazyJsdocTag<'_>) -> String {
413.         if !matches!(tag_name, "param" | "arg" | "argument") {
414.             if let Some(raw_body) = tag.raw_body().map(str::trim).filter(|value| !value.is_empty())
415.             {
416.                 return raw_body.to_string();
417.             }
418.         }
419. 
420.         let mut parts = Vec::new();
421. 
422.         if let Some(raw_type) = tag.raw_type() {
423.             let raw_type = raw_type.raw().trim();
424.             if !raw_type.is_empty() {
425.                 parts.push(format!("{{{raw_type}}}"));
426.             }
427.         }
428. 
429.         if let Some(name) = tag.name() {
430.             let name = name.raw().trim();
431.             if !name.is_empty() {
432.                 let name = if tag.optional() {
433.                     tag.default_value().map_or_else(
434.                         || format!("[{name}]"),
435.                         |default_value| format!("[{name}={default_value}]"),
436.                     )
437.                 } else {
438.                     name.to_string()
439.                 };
440.                 parts.push(name);
441.             }
442.         }
443. 
444.         if let Some(description) =
445.             tag.description().map(str::trim).filter(|value| !value.is_empty())
446.         {
447.             if parts.is_empty() {
448.                 parts.push(description.to_string());
449.             } else {
450.                 parts.push(format!("- {description}"));
451.             }
452.         }
453. 
454.         if !parts.is_empty() {
455.             return parts.join(" ");
456.         }
457. 
458.         if let Some(raw_body) = tag.raw_body().map(str::trim).filter(|value| !value.is_empty()) {
459.             return raw_body.to_string();
460.         }
461. 
462.         tag.body().map_or_else(String::new, |body| match body {
463.             LazyJsdocTagBody::Generic(body) => body.description().unwrap_or_default().to_string(),
464.             LazyJsdocTagBody::Raw(body) => body.raw().to_string(),
465.             LazyJsdocTagBody::Borrows(_) => String::new(),
466.         })
467.     }
468. 
469.     /// Fallback parser used when the external JSDoc parser cannot produce a root.
470.     fn parse_jsdoc_fallback(comment: &str) -> (String, Vec<DocTag>) {
471.         let mut description_lines = Vec::new();
472.         let mut tags = Vec::new();
473.         let mut current_tag: Option<(String, Vec<String>)> = None;
474. 
475.         let lines: Vec<String> = comment
476.             .lines()
477.             .map(|line| {
478.                 let trimmed = line.trim_start();
479.                 let trimmed = trimmed.strip_prefix('*').unwrap_or(trimmed);
480.                 trimmed.strip_prefix(' ').unwrap_or(trimmed).trim_end().to_string()
481.             })
482.             .collect();
483. 
484.         for line in lines {
485.             let trimmed = line.trim_start();
486.             if let Some(without_at) = trimmed.strip_prefix('@') {
487.                 // Save previous tag if any
488.                 if let Some((tag, value_lines)) = current_tag.take() {
489.                     tags.push(DocTag::new(tag, value_lines.join("\n").trim().to_string()));
490.                 }
491. 
492.                 let split_at = without_at
493.                     .char_indices()
494.                     .find_map(|(index, ch)| ch.is_whitespace().then_some(index))
495.                     .unwrap_or(without_at.len());
496.                 let tag_name = without_at[..split_at].to_string();
497.                 let tag_value = without_at[split_at..].trim_start().to_string();
498.                 current_tag = Some((tag_name, vec![tag_value]));
499.             } else if let Some((_, ref mut value_lines)) = current_tag {
500.                 value_lines.push(line);
501.             } else {
502.                 description_lines.push(line);
503.             }
504.         }
505. 
506.         // Save last tag if any
507.         if let Some((tag, value_lines)) = current_tag {
508.             tags.push(DocTag::new(tag, value_lines.join("\n").trim().to_string()));
509.         }
510. 
511.         (description_lines.join("\n").trim().to_string(), tags)
512.     }
