526.     fn format_formal_parameters(&self, params: &oxc_ast::ast::FormalParameters<'a>) -> String {
527.         let mut items = params
528.             .items
529.             .iter()
530.             .map(|param| self.slice(param.span.start, param.span.end))
531.             .collect::<Vec<_>>();
532. 
533.         if let Some(rest) = &params.rest {
534.             items.push(format!(
535.                 "...{}",
536.                 self.slice(rest.argument.span().start, rest.argument.span().end)
537.             ));
538.         }
539. 
540.         items.join(", ")
541.     }
