543.     fn format_function_signature(&self, func: &Function<'a>, name: &str, exported: bool) -> String {
544.         let mut sig = String::new();
545. 
546.         if exported {
547.             sig.push_str("export ");
548.         }
549.         if func.declare {
550.             sig.push_str("declare ");
551.         }
552.         if func.r#async {
553.             sig.push_str("async ");
554.         }
555.         sig.push_str("function ");
556.         if func.generator {
557.             sig.push('*');
558.         }
559.         sig.push_str(name);
560.         sig.push_str(&self.format_type_parameter_declaration(func.type_parameters.as_ref()));
561.         sig.push('(');
562.         sig.push_str(&self.format_formal_parameters(&func.params));
563.         sig.push(')');
564. 
565.         if let Some(return_type) = func.return_type.as_ref() {
566.             sig.push_str(": ");
567.             sig.push_str(&self.slice(
568.                 return_type.type_annotation.span().start,
569.                 return_type.type_annotation.span().end,
570.             ));
571.         }
572. 
573.         sig
574.     }
