607.     fn format_class_signature(&self, class: &Class, name: &str, exported: bool) -> String {
608.         let mut sig = String::new();
609.         if exported {
610.             sig.push_str("export ");
611.         }
612.         if class.r#abstract {
613.             sig.push_str("abstract ");
614.         }
615.         if class.declare {
616.             sig.push_str("declare ");
617.         }
618.         sig.push_str("class ");
619.         sig.push_str(name);
620.         sig.push_str(&self.format_type_parameter_declaration(class.type_parameters.as_ref()));
621. 
622.         if let Some(super_class) = &class.super_class {
623.             sig.push_str(" extends ");
624.             sig.push_str(&self.slice(super_class.span().start, super_class.span().end));
625.             if let Some(type_params) = &class.super_type_parameters {
626.                 sig.push_str(&self.format_type_parameter_declaration(Some(type_params)));
627.             }
628.         }
629. 
630.         if let Some(implements) = &class.implements {
631.             let implements = implements
632.                 .iter()
633.                 .map(|item| {
634.                     let mut value =
635.                         self.slice(item.expression.span().start, item.expression.span().end);
636.                     if let Some(type_params) = &item.type_parameters {
637.                         value.push_str(&self.format_type_parameter_declaration(Some(type_params)));
638.                     }
639.                     value
640.                 })
641.                 .collect::<Vec<_>>()
642.                 .join(", ");
643. 
644.             if !implements.is_empty() {
645.                 sig.push_str(" implements ");
646.                 sig.push_str(&implements);
647.             }
648.         }
649. 
650.         sig
651.     }
