721.     fn split_leading_jsdoc_type(value: &str) -> (Option<String>, &str) {
722.         let value = value.trim_start();
723.         let Some(rest) = value.strip_prefix('{') else {
724.             return (None, value);
725.         };
726. 
727.         let mut depth = 1_u32;
728.         for (index, ch) in rest.char_indices() {
729.             match ch {
730.                 '{' => depth += 1,
731.                 '}' => {
732.                     depth = depth.saturating_sub(1);
733.                     if depth == 0 {
734.                         let type_annotation = rest[..index].trim();
735.                         let remaining = rest[index + ch.len_utf8()..].trim_start();
736.                         return (
737.                             (!type_annotation.is_empty()).then(|| type_annotation.to_string()),
738.                             remaining,
739.                         );
740.                     }
741.                 }
742.                 _ => {}
743.             }
744.         }
745. 
746.         (None, value)
747.     }
748. 
749.     fn clean_tag_description(value: &str) -> Option<String> {
750.         let value = value.trim();
751.         let value = value.strip_prefix('-').map_or(value, str::trim_start).trim();
752.         (!value.is_empty()).then(|| value.to_string())
753.     }
754. 
755.     fn split_name_and_description(value: &str) -> (&str, &str) {
756.         let value = value.trim_start();
757.         if let Some(rest) = value.strip_prefix('[') {
758.             if let Some(close_index) = rest.find(']') {
759.                 let close_index = close_index + 2;
760.                 return (&value[..close_index], value[close_index..].trim_start());
761.             }
762.         }
763. 
764.         value
765.             .char_indices()
766.             .find_map(|(index, ch)| {
767.                 ch.is_whitespace()
768.                     .then_some((&value[..index], value[index + ch.len_utf8()..].trim_start()))
769.             })
770.             .unwrap_or((value, ""))
771.     }
772. 
773.     fn parse_param_tag_value(value: &str) -> Option<ParsedParamTag> {
774.         let (type_annotation, rest) = Self::split_leading_jsdoc_type(value);
775.         let (name, description) = Self::split_name_and_description(rest);
776.         let mut name = name.trim().to_string();
777.         if name.is_empty() {
778.             return None;
779.         }
780. 
781.         let mut optional = false;
782.         let mut default_value = None;
783.         if name.starts_with('[') && name.ends_with(']') {
784.             optional = true;
785.             let inner = name[1..name.len() - 1].to_string();
786.             if let Some((inner_name, inner_default)) = inner.split_once('=') {
787.                 name = inner_name.trim().to_string();
788.                 let inner_default = inner_default.trim();
789.                 if !inner_default.is_empty() {
790.                     default_value = Some(inner_default.to_string());
791.                 }
792.             } else {
793.                 name = inner.trim().to_string();
794.             }
795.         }
796. 
797.         (!name.is_empty()).then(|| ParsedParamTag {
798.             name,
799.             type_annotation,
800.             optional,
801.             default_value,
802.             description: Self::clean_tag_description(description),
803.         })
804.     }
805. 
806.     fn parse_param_tag(tag: &DocTag) -> Option<ParsedParamTag> {
807.         if tag.name.is_none()
808.             && tag.type_annotation.is_none()
809.             && tag.default_value.is_none()
810.             && tag.description.is_none()
811.         {
812.             return Self::parse_param_tag_value(&tag.value);
813.         }
814. 
815.         let name = tag.name.as_ref()?.trim().to_string();
816.         (!name.is_empty()).then(|| ParsedParamTag {
817.             name,
818.             type_annotation: tag.type_annotation.clone(),
819.             optional: tag.optional.unwrap_or(false),
820.             default_value: tag.default_value.clone(),
821.             description: tag.description.clone(),
822.         })
823.     }
824. 
825.     fn find_param_tag(tags: &[DocTag], name: &str) -> Option<ParsedParamTag> {
826.         tags.iter()
827.             .filter(|tag| matches!(tag.tag.as_str(), "param" | "arg" | "argument"))
828.             .filter_map(Self::parse_param_tag)
829.             .find(|tag| {
830.                 let tag_name = tag.name.trim_start_matches("...");
831.                 tag_name == name || tag_name.split('.').next() == Some(name)
832.             })
833.     }
834. 
835.     fn parse_return_tag(tag: &DocTag) -> (Option<String>, Option<String>) {
836.         if tag.type_annotation.is_some() || tag.description.is_some() {
837.             return (tag.type_annotation.clone(), tag.description.clone());
838.         }
839. 
840.         let (type_annotation, rest) = Self::split_leading_jsdoc_type(&tag.value);
841.         (type_annotation, Self::clean_tag_description(rest))
842.     }
