867.     /// Format a binding pattern.
868.     fn format_binding_pattern(&self, pattern: &oxc_ast::ast::BindingPattern) -> String {
869.         match &pattern.kind {
870.             BindingPatternKind::BindingIdentifier(id) => {
871.                 let mut s = id.name.to_string();
872.                 if pattern.optional {
873.                     s.push('?');
874.                 }
875.                 if let Some(type_ann) = &pattern.type_annotation {
876.                     s.push_str(": ");
877.                     s.push_str(&self.format_ts_type(&type_ann.type_annotation));
878.                 }
879.                 s
880.             }
881.             BindingPatternKind::ObjectPattern(_) => "{...}".to_string(),
882.             BindingPatternKind::ArrayPattern(_) => "[...]".to_string(),
883.             BindingPatternKind::AssignmentPattern(assign) => {
884.                 self.format_binding_pattern(&assign.left)
885.             }
886.         }
887.     }
