957.     fn extract_params_from_formals(
958.         &self,
959.         params: &oxc_ast::ast::FormalParameters<'a>,
960.         tags: &[DocTag],
961.     ) -> Vec<ParamDoc> {
962.         let mut docs = params
963.             .items
964.             .iter()
965.             .map(|param| {
966.                 let name = Self::binding_pattern_name(&param.pattern);
967.                 let tag = Self::find_param_tag(tags, &name);
968.                 let default_value = self
969.                     .binding_pattern_default_value(&param.pattern)
970.                     .or_else(|| tag.as_ref().and_then(|tag| tag.default_value.clone()));
971. 
972.                 let type_annotation = param
973.                     .pattern
974.                     .type_annotation
975.                     .as_ref()
976.                     .map(|t| self.format_ts_type(&t.type_annotation))
977.                     .or_else(|| tag.as_ref().and_then(|tag| tag.type_annotation.clone()));
978. 
979.                 let optional = param.pattern.optional
980.                     || default_value.is_some()
981.                     || tag.as_ref().is_some_and(|tag| tag.optional);
982.                 let description = tag.and_then(|tag| tag.description);
983. 
984.                 ParamDoc { name, type_annotation, optional, default_value, description }
985.             })
986.             .collect::<Vec<_>>();
987. 
988.         if let Some(rest) = params.rest.as_ref() {
989.             let name = Self::binding_pattern_name(&rest.argument);
990.             let tag = Self::find_param_tag(tags, &name);
991.             let type_annotation = rest
992.                 .argument
993.                 .type_annotation
994.                 .as_ref()
995.                 .map(|t| self.format_ts_type(&t.type_annotation))
996.                 .or_else(|| tag.as_ref().and_then(|tag| tag.type_annotation.clone()));
997. 
998.             docs.push(ParamDoc {
999.                 name,
1000.                 type_annotation,
1001.                 optional: tag.as_ref().is_some_and(|tag| tag.optional),
1002.                 default_value: tag.as_ref().and_then(|tag| tag.default_value.clone()),
1003.                 description: tag.and_then(|tag| tag.description),
1004.             });
1005.         }
1006. 
1007.         docs
1008.     }
1009. 
1010.     /// Extract parameters from a function.
1011.     fn extract_params(&self, func: &Function, tags: &[DocTag]) -> Vec<ParamDoc> {
1012.         self.extract_params_from_formals(&func.params, tags)
1013.     }
