1015.     fn extract_return_type_from_annotation(
1016.         &self,
1017.         return_type: Option<&oxc_allocator::Box<'a, oxc_ast::ast::TSTypeAnnotation<'a>>>,
1018.         tags: &[DocTag],
1019.     ) -> Option<String> {
1020.         return_type.map(|r| self.format_ts_type(&r.type_annotation)).or_else(|| {
1021.             tags.iter().find(|tag| tag.tag == "returns" || tag.tag == "return").and_then(|tag| {
1022.                 let (type_annotation, description) = Self::parse_return_tag(tag);
1023.                 type_annotation.or(description)
1024.             })
1025.         })
1026.     }
1027. 
1028.     /// Extract return type from tags.
1029.     fn extract_return_type(&self, func: &Function, tags: &[DocTag]) -> Option<String> {
1030.         self.extract_return_type_from_annotation(func.return_type.as_ref(), tags)
1031.     }
