1033.     /// Create a DocItem from a function.
1034.     fn create_function_item(
1035.         &self,
1036.         func: &Function,
1037.         exported: bool,
1038.         attached_to: u32,
1039.     ) -> Option<DocItem> {
1040.         let name = func.id.as_ref()?.name.to_string();
1041.         let (jsdoc, doc, tags) = self.extract_jsdoc(attached_to)?;
1042.         if !self.include_private && Self::has_private_tag(&tags) {
1043.             return None;
1044.         }
1045.         let (line, end_line) = self.span_lines(attached_to, func.span.end);
1046. 
1047.         Some(DocItem {
1048.             name,
1049.             kind: DocItemKind::Function,
1050.             doc: if doc.is_empty() { None } else { Some(doc) },
1051.             source_path: self.file_path.to_string(),
1052.             line,
1053.             end_line,
1054.             column: self.column_number(attached_to),
1055.             jsdoc: Some(jsdoc),
1056.             exported,
1057.             signature: Some(self.format_function_signature(
1058.                 func,
1059.                 func.id.as_ref()?.name.as_str(),
1060.                 exported,
1061.             )),
1062.             params: self.extract_params(func, &tags),
1063.             return_type: self.extract_return_type(func, &tags),
1064.             children: Vec::new(),
1065.             tags,
1066.         })
1067.     }
1068. 
1069.     /// Create a DocItem from a class.
1070.     fn create_class_item(
1071.         &self,
1072.         class: &Class,
1073.         name: &str,
1074.         exported: bool,
1075.         attached_to: u32,
1076.     ) -> Option<DocItem> {
1077.         let (jsdoc, doc, tags) = self.extract_jsdoc(attached_to)?;
1078.         if !self.include_private && Self::has_private_tag(&tags) {
1079.             return None;
1080.         }
1081.         let (line, end_line) = self.span_lines(attached_to, class.span.end);
1082. 
1083.         let mut children = Vec::new();
1084. 
1085.         // Extract class members
1086.         for element in &class.body.body {
1087.             match element {
1088.                 oxc_ast::ast::ClassElement::MethodDefinition(method) => {
1089.                     let method_name = match &method.key {
1090.                         oxc_ast::ast::PropertyKey::StaticIdentifier(id) => id.name.to_string(),
1091.                         _ => continue,
1092.                     };
1093. 
1094.                     let kind = match method.kind {
1095.                         oxc_ast::ast::MethodDefinitionKind::Constructor => DocItemKind::Constructor,
1096.                         oxc_ast::ast::MethodDefinitionKind::Get => DocItemKind::Getter,
