368.     fn convert_jsdoc_tag(tag: LazyJsdocTag<'_>) -> DocTag {
369.         let tag_name = tag.tag().value().to_string();
370.         let value = Self::format_jsdoc_tag_value(&tag_name, &tag);
371.         let type_annotation = tag
372.             .raw_type()
373.             .map(|raw_type| raw_type.raw().trim().to_string())
374.             .filter(|value| !value.is_empty());
375.         let name =
376.             tag.name().map(|name| name.raw().trim().to_string()).filter(|value| !value.is_empty());
377.         let optional = name.as_ref().map(|_| tag.optional());
378.         let default_value = tag.default_value().map(str::trim).filter(|value| !value.is_empty());
379.         let description =
380.             Self::format_structured_tag_description(&tag_name, &tag, type_annotation.as_deref());
381. 
382.         DocTag {
383.             tag: tag_name,
384.             value,
385.             type_annotation,
386.             name,
387.             optional,
388.             default_value: default_value.map(str::to_string),
389.             description,
390.         }
391.     }
392. 
393.     fn format_structured_tag_description(
394.         tag_name: &str,
395.         tag: &LazyJsdocTag<'_>,
396.         type_annotation: Option<&str>,
397.     ) -> Option<String> {
398.         if matches!(tag_name, "returns" | "return") {
399.             let raw_body = tag.raw_body().map(str::trim).filter(|value| !value.is_empty())?;
400.             let without_type = type_annotation
401.                 .and_then(|type_annotation| {
402.                     raw_body.strip_prefix(&format!("{{{type_annotation}}}")).map(str::trim_start)
403.                 })
404.                 .unwrap_or(raw_body);
405.             return Self::clean_tag_description(without_type);
406.         }
407. 
408.         tag.description().and_then(Self::clean_tag_description)
409.     }
410. 
411.     fn format_jsdoc_tag_value(tag_name: &str, tag: &LazyJsdocTag<'_>) -> String {
412.         if !matches!(tag_name, "param" | "arg" | "argument") {
413.             if let Some(raw_body) = tag.raw_body().map(str::trim).filter(|value| !value.is_empty())
414.             {
415.                 return raw_body.to_string();
416.             }
417.         }
418. 
419.         let mut parts = Vec::new();
420. 
421.         if let Some(raw_type) = tag.raw_type() {
422.             let raw_type = raw_type.raw().trim();
423.             if !raw_type.is_empty() {
424.                 parts.push(format!("{{{raw_type}}}"));
425.             }
426.         }
427. 
428.         if let Some(name) = tag.name() {
429.             let name = name.raw().trim();
430.             if !name.is_empty() {
431.                 let name = if tag.optional() {
432.                     tag.default_value().map_or_else(
433.                         || format!("[{name}]"),
434.                         |default_value| format!("[{name}={default_value}]"),
435.                     )
436.                 } else {
437.                     name.to_string()
438.                 };
439.                 parts.push(name);
440.             }
441.         }
442. 
443.         if let Some(description) =
444.             tag.description().map(str::trim).filter(|value| !value.is_empty())
445.         {
446.             if parts.is_empty() {
447.                 parts.push(description.to_string());
448.             } else {
449.                 parts.push(format!("- {description}"));
450.             }
451.         }
452. 
453.         if !parts.is_empty() {
454.             return parts.join(" ");
455.         }
456. 
457.         if let Some(raw_body) = tag.raw_body().map(str::trim).filter(|value| !value.is_empty()) {
458.             return raw_body.to_string();
459.         }
460. 
461.         tag.body().map_or_else(String::new, |body| match body {
462.             LazyJsdocTagBody::Generic(body) => body.description().unwrap_or_default().to_string(),
463.             LazyJsdocTagBody::Raw(body) => body.raw().to_string(),
464.             LazyJsdocTagBody::Borrows(_) => String::new(),
465.         })
466.     }
467. 
468.     /// Fallback parser used when the external JSDoc parser cannot produce a root.
469.     fn parse_jsdoc_fallback(comment: &str) -> (String, Vec<DocTag>) {
470.         let mut description_lines = Vec::new();
471.         let mut tags = Vec::new();
472.         let mut current_tag: Option<(String, Vec<String>)> = None;
473. 
474.         let lines: Vec<String> = comment
475.             .lines()
476.             .map(|line| {
477.                 let trimmed = line.trim_start();
478.                 let trimmed = trimmed.strip_prefix('*').unwrap_or(trimmed);
479.                 trimmed.strip_prefix(' ').unwrap_or(trimmed).trim_end().to_string()
480.             })
481.             .collect();
482. 
483.         for line in lines {
484.             let trimmed = line.trim_start();
485.             if let Some(without_at) = trimmed.strip_prefix('@') {
486.                 // Save previous tag if any
487.                 if let Some((tag, value_lines)) = current_tag.take() {
488.                     tags.push(DocTag::new(tag, value_lines.join("\n").trim().to_string()));
489.                 }
490. 
491.                 let split_at = without_at
492.                     .char_indices()
493.                     .find_map(|(index, ch)| ch.is_whitespace().then_some(index))
494.                     .unwrap_or(without_at.len());
495.                 let tag_name = without_at[..split_at].to_string();
496.                 let tag_value = without_at[split_at..].trim_start().to_string();
497.                 current_tag = Some((tag_name, vec![tag_value]));
498.             } else if let Some((_, ref mut value_lines)) = current_tag {
499.                 value_lines.push(line);
500.             } else {
501.                 description_lines.push(line);
502.             }
503.         }
504. 
505.         // Save last tag if any
506.         if let Some((tag, value_lines)) = current_tag {
507.             tags.push(DocTag::new(tag, value_lines.join("\n").trim().to_string()));
508.         }
509. 
510.         (description_lines.join("\n").trim().to_string(), tags)
511.     }
