513.     fn format_type_parameter_declaration<T>(
514.         &self,
515.         type_params: Option<&oxc_allocator::Box<'a, T>>,
516.     ) -> String
517.     where
518.         T: oxc_span::GetSpan,
519.     {
520.         type_params
521.             .map(|type_params| self.slice(type_params.span().start, type_params.span().end))
522.             .unwrap_or_default()
523.     }
