525.     fn format_formal_parameters(&self, params: &oxc_ast::ast::FormalParameters<'a>) -> String {
526.         let mut items = params
527.             .items
528.             .iter()
529.             .map(|param| self.slice(param.span.start, param.span.end))
530.             .collect::<Vec<_>>();
531. 
532.         if let Some(rest) = &params.rest {
533.             items.push(format!(
534.                 "...{}",
535.                 self.slice(rest.argument.span().start, rest.argument.span().end)
536.             ));
537.         }
538. 
539.         items.join(", ")
540.     }
