223.     /// Extracts documentation from a JavaScript/TypeScript file.
224.     fn extract_js_ts(&self, path: &Path) -> ExtractResult<Vec<DocItem>> {
225.         let content = std::fs::read_to_string(path)?;
226.         let file_path = path.to_string_lossy().to_string();
227.         let source_type = SourceType::from_path(path).unwrap_or_default();
228. 
229.         self.extract_source(&content, &file_path, source_type)
230.     }
231. }
