239. /// Pre-parsed JSDoc data for one comment: `(raw, description, tags)`.
240. type ParsedJsdoc = (String, String, Vec<DocTag>);
241. 
242. /// Extract the JSDoc content body from a comment with a single allocation.
243. fn extract_raw_jsdoc(comment: &Comment, source: &str) -> String {
244.     let content = comment.content_span().source_text(source);
245.     let trimmed = content.strip_prefix('*').unwrap_or(content);
246.     trimmed.trim_matches('\n').to_string()
247. }
248. 
249. /// Pre-parse every JSDoc comment in the program with a single batch call so the
250. /// AST visitor can resolve documentation by `attached_to` via a cheap lookup.
251. fn build_jsdoc_cache(source: &str, comments: &[Comment]) -> FxHashMap<u32, ParsedJsdoc> {
252.     let jsdoc_comments: Vec<&Comment> =
253.         comments.iter().filter(|comment| comment.is_jsdoc(source)).collect();
254.     if jsdoc_comments.is_empty() {
255.         return FxHashMap::default();
256.     }
257. 
258.     let items: Vec<JsdocBatchItem<'_>> = jsdoc_comments
259.         .iter()
260.         .map(|comment| JsdocBatchItem {
261.             source_text: comment.span.source_text(source),
262.             base_offset: comment.span.start,
263.         })
264.         .collect();
265. 
266.     let options = JsdocParseOptions { preserve_whitespace: true, ..JsdocParseOptions::default() };
267.     let result = parse_jsdoc_batch_to_bytes(&items, options);
268. 
269.     let failed: FxHashSet<u32> =
270.         result.diagnostics.iter().map(|diagnostic| diagnostic.root_index).collect();
271. 
272.     let mut cache: FxHashMap<u32, ParsedJsdoc> =
273.         FxHashMap::with_capacity_and_hasher(jsdoc_comments.len(), FxBuildHasher);
274. 
275.     if let Ok(source_file) =
276.         ox_jsdoc::decoder::source_file::LazySourceFile::new(&result.binary_bytes)
277.     {
278.         for (index, (comment, root)) in jsdoc_comments.iter().zip(source_file.asts()).enumerate() {
279.             let raw = extract_raw_jsdoc(comment, source);
280.             let (doc, tags) = match root {
281.                 Some(root) if !failed.contains(&(index as u32)) => {
282.                     let doc = root
283.                         .description_text(false)
284.                         .map_or_else(String::new, |description| description.trim().to_string());
285.                     let tags = root.tags().map(DocVisitor::convert_jsdoc_tag).collect();
286.                     (doc, tags)
287.                 }
288.                 _ => DocVisitor::parse_jsdoc_fallback(&raw),
289.             };
290.             cache.insert(comment.attached_to, (raw, doc, tags));
291.         }
292.     } else {
293.         for comment in &jsdoc_comments {
294.             let raw = extract_raw_jsdoc(comment, source);
295.             let (doc, tags) = DocVisitor::parse_jsdoc_fallback(&raw);
296.             cache.insert(comment.attached_to, (raw, doc, tags));
297.         }
298.     }
299. 
300.     cache
301. }
