542.     fn format_function_signature(&self, func: &Function<'a>, name: &str, exported: bool) -> String {
543.         let mut sig = String::new();
544. 
545.         if exported {
546.             sig.push_str("export ");
547.         }
548.         if func.declare {
549.             sig.push_str("declare ");
550.         }
551.         if func.r#async {
552.             sig.push_str("async ");
553.         }
554.         sig.push_str("function ");
555.         if func.generator {
556.             sig.push('*');
557.         }
558.         sig.push_str(name);
559.         sig.push_str(&self.format_type_parameter_declaration(func.type_parameters.as_ref()));
560.         sig.push('(');
561.         sig.push_str(&self.format_formal_parameters(&func.params));
562.         sig.push(')');
563. 
564.         if let Some(return_type) = func.return_type.as_ref() {
565.             sig.push_str(": ");
566.             sig.push_str(&self.slice(
567.                 return_type.type_annotation.span().start,
568.                 return_type.type_annotation.span().end,
569.             ));
570.         }
571. 
572.         sig
573.     }
