575.     fn format_assigned_function_signature(
576.         &self,
577.         name: &str,
578.         r#async: bool,
579.         type_parameters: Option<
580.             &oxc_allocator::Box<'a, oxc_ast::ast::TSTypeParameterDeclaration<'a>>,
581.         >,
582.         params: &oxc_ast::ast::FormalParameters<'a>,
583.         return_type: Option<&oxc_allocator::Box<'a, oxc_ast::ast::TSTypeAnnotation<'a>>>,
584.     ) -> String {
585.         let mut sig = String::new();
586.         if r#async {
587.             sig.push_str("async ");
588.         }
589.         sig.push_str(name);
590.         sig.push_str(&self.format_type_parameter_declaration(type_parameters));
591.         sig.push('(');
592.         sig.push_str(&self.format_formal_parameters(params));
593.         sig.push(')');
594. 
595.         if let Some(return_type) = return_type {
596.             sig.push_str(": ");
597.             sig.push_str(&self.slice(
598.                 return_type.type_annotation.span().start,
599.                 return_type.type_annotation.span().end,
600.             ));
601.         }
602. 
603.         sig
604.     }
