720.     fn split_leading_jsdoc_type(value: &str) -> (Option<String>, &str) {
721.         let value = value.trim_start();
722.         let Some(rest) = value.strip_prefix('{') else {
723.             return (None, value);
724.         };
725. 
726.         let mut depth = 1_u32;
727.         for (index, ch) in rest.char_indices() {
728.             match ch {
729.                 '{' => depth += 1,
730.                 '}' => {
731.                     depth = depth.saturating_sub(1);
732.                     if depth == 0 {
733.                         let type_annotation = rest[..index].trim();
734.                         let remaining = rest[index + ch.len_utf8()..].trim_start();
735.                         return (
736.                             (!type_annotation.is_empty()).then(|| type_annotation.to_string()),
737.                             remaining,
738.                         );
739.                     }
740.                 }
741.                 _ => {}
742.             }
743.         }
744. 
745.         (None, value)
746.     }
747. 
748.     fn clean_tag_description(value: &str) -> Option<String> {
749.         let value = value.trim();
750.         let value = value.strip_prefix('-').map_or(value, str::trim_start).trim();
751.         (!value.is_empty()).then(|| value.to_string())
752.     }
753. 
754.     fn split_name_and_description(value: &str) -> (&str, &str) {
755.         let value = value.trim_start();
756.         if let Some(rest) = value.strip_prefix('[') {
757.             if let Some(close_index) = rest.find(']') {
758.                 let close_index = close_index + 2;
759.                 return (&value[..close_index], value[close_index..].trim_start());
760.             }
761.         }
762. 
763.         value
764.             .char_indices()
765.             .find_map(|(index, ch)| {
766.                 ch.is_whitespace()
767.                     .then_some((&value[..index], value[index + ch.len_utf8()..].trim_start()))
768.             })
769.             .unwrap_or((value, ""))
770.     }
771. 
772.     fn parse_param_tag_value(value: &str) -> Option<ParsedParamTag> {
773.         let (type_annotation, rest) = Self::split_leading_jsdoc_type(value);
774.         let (name, description) = Self::split_name_and_description(rest);
775.         let mut name = name.trim().to_string();
776.         if name.is_empty() {
777.             return None;
778.         }
779. 
780.         let mut optional = false;
781.         let mut default_value = None;
782.         if name.starts_with('[') && name.ends_with(']') {
783.             optional = true;
784.             let inner = name[1..name.len() - 1].to_string();
785.             if let Some((inner_name, inner_default)) = inner.split_once('=') {
786.                 name = inner_name.trim().to_string();
787.                 let inner_default = inner_default.trim();
788.                 if !inner_default.is_empty() {
789.                     default_value = Some(inner_default.to_string());
790.                 }
791.             } else {
792.                 name = inner.trim().to_string();
793.             }
794.         }
795. 
796.         (!name.is_empty()).then(|| ParsedParamTag {
797.             name,
798.             type_annotation,
799.             optional,
800.             default_value,
801.             description: Self::clean_tag_description(description),
802.         })
803.     }
804. 
805.     fn parse_param_tag(tag: &DocTag) -> Option<ParsedParamTag> {
806.         if tag.name.is_none()
807.             && tag.type_annotation.is_none()
808.             && tag.default_value.is_none()
809.             && tag.description.is_none()
810.         {
811.             return Self::parse_param_tag_value(&tag.value);
812.         }
813. 
814.         let name = tag.name.as_ref()?.trim().to_string();
815.         (!name.is_empty()).then(|| ParsedParamTag {
816.             name,
817.             type_annotation: tag.type_annotation.clone(),
818.             optional: tag.optional.unwrap_or(false),
819.             default_value: tag.default_value.clone(),
820.             description: tag.description.clone(),
821.         })
822.     }
823. 
824.     fn find_param_tag(tags: &[DocTag], name: &str) -> Option<ParsedParamTag> {
825.         tags.iter()
826.             .filter(|tag| matches!(tag.tag.as_str(), "param" | "arg" | "argument"))
827.             .filter_map(Self::parse_param_tag)
828.             .find(|tag| {
829.                 let tag_name = tag.name.trim_start_matches("...");
830.                 tag_name == name || tag_name.split('.').next() == Some(name)
831.             })
832.     }
833. 
834.     fn parse_return_tag(tag: &DocTag) -> (Option<String>, Option<String>) {
835.         if tag.type_annotation.is_some() || tag.description.is_some() {
836.             return (tag.type_annotation.clone(), tag.description.clone());
837.         }
838. 
839.         let (type_annotation, rest) = Self::split_leading_jsdoc_type(&tag.value);
840.         (type_annotation, Self::clean_tag_description(rest))
841.     }
842. 
843.     fn binding_pattern_name(pattern: &oxc_ast::ast::BindingPattern) -> String {
844.         match &pattern.kind {
845.             BindingPatternKind::BindingIdentifier(id) => id.name.to_string(),
846.             BindingPatternKind::AssignmentPattern(assign) => {
847.                 Self::binding_pattern_name(&assign.left)
848.             }
849.             BindingPatternKind::ObjectPattern(_) => "param".to_string(),
850.             BindingPatternKind::ArrayPattern(_) => "param".to_string(),
851.         }
852.     }
853. 
854.     fn binding_pattern_default_value(
855.         &self,
856.         pattern: &oxc_ast::ast::BindingPattern,
857.     ) -> Option<String> {
858.         match &pattern.kind {
859.             BindingPatternKind::AssignmentPattern(assign) => {
860.                 Some(self.slice(assign.right.span().start, assign.right.span().end))
861.             }
862.             _ => None,
863.         }
864.     }
865. 
866.     /// Format a binding pattern.
867.     fn format_binding_pattern(&self, pattern: &oxc_ast::ast::BindingPattern) -> String {
868.         match &pattern.kind {
869.             BindingPatternKind::BindingIdentifier(id) => {
870.                 let mut s = id.name.to_string();
871.                 if pattern.optional {
872.                     s.push('?');
873.                 }
874.                 if let Some(type_ann) = &pattern.type_annotation {
875.                     s.push_str(": ");
876.                     s.push_str(&self.format_ts_type(&type_ann.type_annotation));
877.                 }
878.                 s
879.             }
880.             BindingPatternKind::ObjectPattern(_) => "{...}".to_string(),
881.             BindingPatternKind::ArrayPattern(_) => "[...]".to_string(),
882.             BindingPatternKind::AssignmentPattern(assign) => {
883.                 self.format_binding_pattern(&assign.left)
884.             }
885.         }
886.     }
887. 
888.     /// Format a TypeScript type.
889.     fn format_ts_type(&self, ts_type: &TSType) -> String {
890.         match ts_type {
891.             TSType::TSAnyKeyword(_) => "any".to_string(),
892.             TSType::TSBooleanKeyword(_) => "boolean".to_string(),
893.             TSType::TSNumberKeyword(_) => "number".to_string(),
894.             TSType::TSStringKeyword(_) => "string".to_string(),
895.             TSType::TSVoidKeyword(_) => "void".to_string(),
896.             TSType::TSNullKeyword(_) => "null".to_string(),
897.             TSType::TSUndefinedKeyword(_) => "undefined".to_string(),
898.             TSType::TSNeverKeyword(_) => "never".to_string(),
899.             TSType::TSBigIntKeyword(_) => "bigint".to_string(),
900.             TSType::TSSymbolKeyword(_) => "symbol".to_string(),
901.             TSType::TSObjectKeyword(_) => "object".to_string(),
902.             TSType::TSTypeReference(ref_type) => Self::format_ts_type_name(&ref_type.type_name),
903.             TSType::TSArrayType(arr) => format!("{}[]", self.format_ts_type(&arr.element_type)),
904.             TSType::TSUnionType(union) => {
905.                 let types: Vec<String> =
906.                     union.types.iter().map(|t| self.format_ts_type(t)).collect();
907.                 types.join(" | ")
908.             }
909.             TSType::TSIntersectionType(inter) => {
910.                 let types: Vec<String> =
911.                     inter.types.iter().map(|t| self.format_ts_type(t)).collect();
912.                 types.join(" & ")
913.             }
914.             TSType::TSFunctionType(func) => {
915.                 let params: Vec<String> = func
916.                     .params
917.                     .items
918.                     .iter()
919.                     .map(|p| self.format_binding_pattern(&p.pattern))
920.                     .collect();
921.                 let ret = self.format_ts_type(&func.return_type.type_annotation);
922.                 format!("({}) => {}", params.join(", "), ret)
923.             }
924.             TSType::TSTypeLiteral(_) => "{ ... }".to_string(),
925.             TSType::TSTupleType(tuple) => {
926.                 let types: Vec<String> = tuple
927.                     .element_types
928.                     .iter()
929.                     .map(|t| self.format_ts_type(t.to_ts_type()))
930.                     .collect();
931.                 format!("[{}]", types.join(", "))
932.             }
933.             TSType::TSLiteralType(lit) => match &lit.literal {
934.                 oxc_ast::ast::TSLiteral::StringLiteral(s) => format!("\"{}\"", s.value),
935.                 oxc_ast::ast::TSLiteral::NumericLiteral(n) => n
936.                     .raw
937.                     .as_ref()
938.                     .map_or_else(|| n.value.to_string(), std::string::ToString::to_string),
939.                 oxc_ast::ast::TSLiteral::BooleanLiteral(b) => b.value.to_string(),
940.                 _ => "literal".to_string(),
941.             },
942.             _ => "unknown".to_string(),
943.         }
944.     }
945. 
946.     /// Format a TypeScript type name.
947.     fn format_ts_type_name(name: &TSTypeName) -> String {
948.         match name {
949.             TSTypeName::IdentifierReference(id) => id.name.to_string(),
950.             TSTypeName::QualifiedName(qn) => {
951.                 format!("{}.{}", Self::format_ts_type_name(&qn.left), qn.right.name)
952.             }
953.         }
954.     }
955. 
956.     fn extract_params_from_formals(
957.         &self,
958.         params: &oxc_ast::ast::FormalParameters<'a>,
959.         tags: &[DocTag],
960.     ) -> Vec<ParamDoc> {
961.         let mut docs = params
962.             .items
963.             .iter()
964.             .map(|param| {
965.                 let name = Self::binding_pattern_name(&param.pattern);
966.                 let tag = Self::find_param_tag(tags, &name);
967.                 let default_value = self
968.                     .binding_pattern_default_value(&param.pattern)
969.                     .or_else(|| tag.as_ref().and_then(|tag| tag.default_value.clone()));
970. 
971.                 let type_annotation = param
972.                     .pattern
973.                     .type_annotation
974.                     .as_ref()
975.                     .map(|t| self.format_ts_type(&t.type_annotation))
976.                     .or_else(|| tag.as_ref().and_then(|tag| tag.type_annotation.clone()));
977. 
978.                 let optional = param.pattern.optional
979.                     || default_value.is_some()
980.                     || tag.as_ref().is_some_and(|tag| tag.optional);
981.                 let description = tag.and_then(|tag| tag.description);
982. 
983.                 ParamDoc { name, type_annotation, optional, default_value, description }
984.             })
985.             .collect::<Vec<_>>();
986. 
987.         if let Some(rest) = params.rest.as_ref() {
988.             let name = Self::binding_pattern_name(&rest.argument);
989.             let tag = Self::find_param_tag(tags, &name);
990.             let type_annotation = rest
991.                 .argument
992.                 .type_annotation
993.                 .as_ref()
994.                 .map(|t| self.format_ts_type(&t.type_annotation))
995.                 .or_else(|| tag.as_ref().and_then(|tag| tag.type_annotation.clone()));
996. 
997.             docs.push(ParamDoc {
998.                 name,
999.                 type_annotation,
1000.                 optional: tag.as_ref().is_some_and(|tag| tag.optional),
1001.                 default_value: tag.as_ref().and_then(|tag| tag.default_value.clone()),
1002.                 description: tag.and_then(|tag| tag.description),
1003.             });
1004.         }
1005. 
1006.         docs
1007.     }
1008. 
1009.     /// Extract parameters from a function.
1010.     fn extract_params(&self, func: &Function, tags: &[DocTag]) -> Vec<ParamDoc> {
1011.         self.extract_params_from_formals(&func.params, tags)
1012.     }
1013. 
1014.     fn extract_return_type_from_annotation(
1015.         &self,
1016.         return_type: Option<&oxc_allocator::Box<'a, oxc_ast::ast::TSTypeAnnotation<'a>>>,
1017.         tags: &[DocTag],
1018.     ) -> Option<String> {
1019.         return_type.map(|r| self.format_ts_type(&r.type_annotation)).or_else(|| {
1020.             tags.iter().find(|tag| tag.tag == "returns" || tag.tag == "return").and_then(|tag| {
1021.                 let (type_annotation, description) = Self::parse_return_tag(tag);
1022.                 type_annotation.or(description)
1023.             })
1024.         })
1025.     }
1026. 
1027.     /// Extract return type from tags.
1028.     fn extract_return_type(&self, func: &Function, tags: &[DocTag]) -> Option<String> {
1029.         self.extract_return_type_from_annotation(func.return_type.as_ref(), tags)
1030.     }
1031. 
1032.     /// Create a DocItem from a function.
1033.     fn create_function_item(
1034.         &self,
1035.         func: &Function,
1036.         exported: bool,
1037.         attached_to: u32,
1038.     ) -> Option<DocItem> {
1039.         let name = func.id.as_ref()?.name.to_string();
1040.         let (jsdoc, doc, tags) = self.extract_jsdoc(attached_to)?;
1041.         if !self.include_private && Self::has_private_tag(&tags) {
1042.             return None;
1043.         }
1044.         let (line, end_line) = self.span_lines(attached_to, func.span.end);
1045. 
1046.         Some(DocItem {
1047.             name,
1048.             kind: DocItemKind::Function,
1049.             doc: if doc.is_empty() { None } else { Some(doc) },
1050.             source_path: self.file_path.to_string(),
1051.             line,
1052.             end_line,
1053.             column: self.column_number(attached_to),
1054.             jsdoc: Some(jsdoc),
1055.             exported,
1056.             signature: Some(self.format_function_signature(
1057.                 func,
1058.                 func.id.as_ref()?.name.as_str(),
1059.                 exported,
1060.             )),
1061.             params: self.extract_params(func, &tags),
1062.             return_type: self.extract_return_type(func, &tags),
1063.             children: Vec::new(),
1064.             tags,
1065.         })
1066.     }
1067. 
1068.     /// Create a DocItem from a class.
1069.     fn create_class_item(
1070.         &self,
1071.         class: &Class,
1072.         name: &str,
1073.         exported: bool,
1074.         attached_to: u32,
1075.     ) -> Option<DocItem> {
1076.         let (jsdoc, doc, tags) = self.extract_jsdoc(attached_to)?;
1077.         if !self.include_private && Self::has_private_tag(&tags) {
1078.             return None;
1079.         }
1080.         let (line, end_line) = self.span_lines(attached_to, class.span.end);
1081. 
1082.         let mut children = Vec::new();
1083. 
1084.         // Extract class members
1085.         for element in &class.body.body {
1086.             match element {
1087.                 oxc_ast::ast::ClassElement::MethodDefinition(method) => {
1088.                     let method_name = match &method.key {
1089.                         oxc_ast::ast::PropertyKey::StaticIdentifier(id) => id.name.to_string(),
1090.                         _ => continue,
1091.                     };
1092. 
1093.                     let kind = match method.kind {
1094.                         oxc_ast::ast::MethodDefinitionKind::Constructor => DocItemKind::Constructor,
1095.                         oxc_ast::ast::MethodDefinitionKind::Get => DocItemKind::Getter,
1096.                         oxc_ast::ast::MethodDefinitionKind::Set => DocItemKind::Setter,
1097.                         oxc_ast::ast::MethodDefinitionKind::Method => DocItemKind::Method,
1098.                     };
1099. 
1100.                     let Some((method_jsdoc, method_doc, method_tags)) =
1101.                         self.extract_jsdoc(method.span.start)
1102.                     else {
1103.                         continue;
1104.                     };
1105.                     if !self.include_private && Self::has_private_tag(&method_tags) {
1106.                         continue;
1107.                     }
1108.                     let (method_line, method_end_line) =
1109.                         self.span_lines(method.span.start, method.span.end);
1110. 
1111.                     children.push(DocItem {
1112.                         name: method_name,
1113.                         kind,
1114.                         doc: if method_doc.is_empty() { None } else { Some(method_doc) },
1115.                         source_path: self.file_path.to_string(),
1116.                         line: method_line,
1117.                         end_line: method_end_line,
1118.                         column: self.column_number(method.span.start),
1119.                         jsdoc: Some(method_jsdoc),
1120.                         exported: false,
1121.                         signature: Some(self.format_assigned_function_signature(
1122.                             "",
1123.                             method.value.r#async,
1124.                             method.value.type_parameters.as_ref(),
1125.                             &method.value.params,
1126.                             method.value.return_type.as_ref(),
1127.                         )),
1128.                         params: self.extract_params(&method.value, &method_tags),
1129.                         return_type: self.extract_return_type(&method.value, &method_tags),
1130.                         children: Vec::new(),
1131.                         tags: method_tags,
1132.                     });
1133.                 }
1134.                 oxc_ast::ast::ClassElement::PropertyDefinition(prop) => {
1135.                     let prop_name = match &prop.key {
1136.                         oxc_ast::ast::PropertyKey::StaticIdentifier(id) => id.name.to_string(),
1137.                         _ => continue,
1138.                     };
1139. 
1140.                     let Some((prop_jsdoc, prop_doc, prop_tags)) =
1141.                         self.extract_jsdoc(prop.span.start)
1142.                     else {
1143.                         continue;
1144.                     };
1145.                     if !self.include_private && Self::has_private_tag(&prop_tags) {
1146.                         continue;
1147.                     }
1148.                     let (prop_line, prop_end_line) =
1149.                         self.span_lines(prop.span.start, prop.span.end);
1150. 
1151.                     let type_annotation = prop
1152.                         .type_annotation
1153.                         .as_ref()
1154.                         .map(|t| self.format_ts_type(&t.type_annotation));
1155. 
1156.                     children.push(DocItem {
1157.                         name: prop_name,
1158.                         kind: DocItemKind::Property,
1159.                         doc: if prop_doc.is_empty() { None } else { Some(prop_doc) },
1160.                         source_path: self.file_path.to_string(),
1161.                         line: prop_line,
1162.                         end_line: prop_end_line,
1163.                         column: self.column_number(prop.span.start),
1164.                         jsdoc: Some(prop_jsdoc),
1165.                         exported: false,
1166.                         signature: type_annotation,
1167.                         params: Vec::new(),
1168.                         return_type: None,
1169.                         children: Vec::new(),
1170.                         tags: prop_tags,
1171.                     });
1172.                 }
1173.                 _ => {}
1174.             }
1175.         }
1176. 
1177.         Some(DocItem {
1178.             name: name.to_string(),
1179.             kind: DocItemKind::Class,
1180.             doc: if doc.is_empty() { None } else { Some(doc) },
1181.             source_path: self.file_path.to_string(),
1182.             line,
1183.             end_line,
1184.             column: self.column_number(attached_to),
1185.             jsdoc: Some(jsdoc),
1186.             exported,
1187.             signature: Some(self.format_class_signature(class, name, exported)),
1188.             params: Vec::new(),
1189.             return_type: None,
1190.             children,
1191.             tags,
1192.         })
1193.     }
1194. }
1195. 
1196. impl<'a> Visit<'a> for DocVisitor<'a> {
1197.     fn visit_statement(&mut self, stmt: &Statement<'a>) {
1198.         match stmt {
1199.             Statement::ExportNamedDeclaration(export) => {
1200.                 if let Some(ref decl) = export.declaration {
1201.                     self.visit_declaration_as_exported(decl, export.span.start);
1202.                 }
1203.             }
1204.             Statement::ExportDefaultDeclaration(export) => {
1205.                 self.has_default_export = true;
1206.                 match &export.declaration {
1207.                     ExportDefaultDeclarationKind::FunctionDeclaration(func) => {
1208.                         if let Some(item) = self.create_function_item(func, true, export.span.start)
1209.                         {
1210.                             self.items.push(item);
1211.                         }
1212.                     }
1213.                     ExportDefaultDeclarationKind::ClassDeclaration(class) => {
1214.                         let name = class
1215.                             .id
1216.                             .as_ref()
1217.                             .map_or_else(|| "default".to_string(), |id| id.name.to_string());
1218.                         if let Some(item) =
1219.                             self.create_class_item(class, &name, true, export.span.start)
1220.                         {
1221.                             self.items.push(item);
1222.                         }
1223.                     }
1224.                     _ => {}
1225.                 }
1226.             }
1227.             _ => {
1228.                 walk::walk_statement(self, stmt);
1229.             }
1230.         }
1231.     }
1232. 
1233.     fn visit_declaration(&mut self, decl: &Declaration<'a>) {
1234.         // Only visit non-exported declarations
1235.         self.visit_declaration_internal(decl, false, decl.span().start);
1236.     }
1237. }
1238. 
1239. impl<'a> DocVisitor<'a> {
1240.     fn visit_declaration_as_exported(&mut self, decl: &Declaration<'a>, attached_to: u32) {
1241.         self.visit_declaration_internal(decl, true, attached_to);
1242.     }
1243. 
1244.     fn visit_declaration_internal(
1245.         &mut self,
1246.         decl: &Declaration<'a>,
1247.         exported: bool,
1248.         attached_to: u32,
1249.     ) {
1250.         match decl {
1251.             Declaration::FunctionDeclaration(func) => {
1252.                 if let Some(item) = self.create_function_item(func, exported, attached_to) {
1253.                     self.items.push(item);
1254.                 }
1255.             }
1256.             Declaration::ClassDeclaration(class) => {
1257.                 if let Some(id) = &class.id {
1258.                     let name = id.name.to_string();
1259.                     if let Some(item) = self.create_class_item(class, &name, exported, attached_to)
1260.                     {
1261.                         self.items.push(item);
1262.                     }
1263.                 }
1264.             }
1265.             Declaration::VariableDeclaration(var_decl) => {
1266.                 let Some((jsdoc, doc, tags)) = self.extract_jsdoc(attached_to) else {
1267.                     return;
1268.                 };
1269.                 if !self.include_private && Self::has_private_tag(&tags) {
1270.                     return;
1271.                 }
1272.                 let (line, end_line) = self.span_lines(attached_to, var_decl.span.end);
1273. 
1274.                 for declarator in &var_decl.declarations {
1275.                     if let BindingPatternKind::BindingIdentifier(id) = &declarator.id.kind {
1276.                         let name = id.name.to_string();
1277. 
1278.                         let Some(initializer) = &declarator.init else {
1279.                             continue;
1280.                         };
1281. 
1282.                         match initializer {
1283.                             Expression::ArrowFunctionExpression(arrow) => {
1284.                                 self.items.push(DocItem {
1285.                                     name: name.clone(),
1286.                                     kind: DocItemKind::Function,
1287.                                     doc: if doc.is_empty() { None } else { Some(doc.clone()) },
1288.                                     source_path: self.file_path.to_string(),
1289.                                     line,
1290.                                     end_line,
1291.                                     column: self.column_number(attached_to),
1292.                                     jsdoc: Some(jsdoc.clone()),
1293.                                     exported,
1294.                                     signature: Some(self.format_assigned_function_signature(
1295.                                         &name,
1296.                                         arrow.r#async,
1297.                                         arrow.type_parameters.as_ref(),
1298.                                         &arrow.params,
1299.                                         arrow.return_type.as_ref(),
1300.                                     )),
1301.                                     params: self.extract_params_from_formals(&arrow.params, &tags),
1302.                                     return_type: self.extract_return_type_from_annotation(
1303.                                         arrow.return_type.as_ref(),
1304.                                         &tags,
1305.                                     ),
1306.                                     children: Vec::new(),
1307.                                     tags: tags.clone(),
1308.                                 });
1309.                             }
1310.                             Expression::FunctionExpression(func_expr) => {
1311.                                 self.items.push(DocItem {
1312.                                     name: name.clone(),
1313.                                     kind: DocItemKind::Function,
1314.                                     doc: if doc.is_empty() { None } else { Some(doc.clone()) },
1315.                                     source_path: self.file_path.to_string(),
1316.                                     line,
1317.                                     end_line,
1318.                                     column: self.column_number(attached_to),
1319.                                     jsdoc: Some(jsdoc.clone()),
1320.                                     exported,
1321.                                     signature: Some(self.format_assigned_function_signature(
1322.                                         &name,
1323.                                         func_expr.r#async,
1324.                                         func_expr.type_parameters.as_ref(),
1325.                                         &func_expr.params,
1326.                                         func_expr.return_type.as_ref(),
1327.                                     )),
1328.                                     params: self.extract_params(func_expr, &tags),
1329.                                     return_type: self.extract_return_type(func_expr, &tags),
1330.                                     children: Vec::new(),
1331.                                     tags: tags.clone(),
1332.                                 });
1333.                             }
1334.                             _ => {}
1335.                         }
1336.                     }
1337.                 }
1338.             }
1339.             Declaration::TSTypeAliasDeclaration(type_alias) => {
1340.                 let Some((jsdoc, doc, tags)) = self.extract_jsdoc(attached_to) else {
1341.                     return;
1342.                 };
1343.                 if !self.include_private && Self::has_private_tag(&tags) {
1344.                     return;
1345.                 }
1346.                 let (line, end_line) = self.span_lines(attached_to, type_alias.span.end);
1347. 
1348.                 self.items.push(DocItem {
1349.                     name: type_alias.id.name.to_string(),
1350.                     kind: DocItemKind::Type,
1351.                     doc: if doc.is_empty() { None } else { Some(doc) },
1352.                     source_path: self.file_path.to_string(),
1353.                     line,
1354.                     end_line,
1355.                     column: self.column_number(attached_to),
1356.                     jsdoc: Some(jsdoc),
1357.                     exported,
1358.                     signature: Some(self.format_type_alias_signature(type_alias, exported)),
1359.                     params: Vec::new(),
1360.                     return_type: None,
1361.                     children: Vec::new(),
1362.                     tags,
1363.                 });
1364.             }
1365.             Declaration::TSInterfaceDeclaration(interface) => {
1366.                 let Some((jsdoc, doc, tags)) = self.extract_jsdoc(attached_to) else {
1367.                     return;
1368.                 };
