1. //! Documentation extraction from source code using OXC parser.
2. 
3. use ox_jsdoc::decoder::nodes::comment_ast::{LazyJsdocTag, LazyJsdocTagBody};
4. use ox_jsdoc::parser::{
5.     parse_batch_to_bytes as parse_jsdoc_batch_to_bytes, BatchItem as JsdocBatchItem,
6.     ParseOptions as JsdocParseOptions,
7. };
8. use oxc_allocator::Allocator;
9. use oxc_ast::ast::{
10.     BindingPattern, Class, Comment, Declaration, ExportDefaultDeclarationKind, Expression,
11.     Function, Statement, TSSignature, TSType, TSTypeName,
12. };
13. use oxc_ast_visit::{walk, Visit};
14. use oxc_parser::Parser;
15. use oxc_span::{GetSpan, SourceType};
16. use rustc_hash::{FxBuildHasher, FxHashMap, FxHashSet};
17. use serde::{Deserialize, Serialize};
18. use std::path::Path;
19. use thiserror::Error;
20. 
21. /// Result type for extraction operations.
22. pub type ExtractResult<T> = Result<T, ExtractError>;
23. 
24. /// Errors during documentation extraction.
25. #[derive(Debug, Error)]
26. pub enum ExtractError {
27.     /// IO error.
28.     #[error("IO error: {0}")]
29.     Io(#[from] std::io::Error),
30. 
31.     /// Parse error.
32.     #[error("Parse error: {0}")]
33.     Parse(String),
34. 
35.     /// Unsupported file type.
36.     #[error("Unsupported file type: {0}")]
37.     UnsupportedFile(String),
38. }
39. 
40. /// Documentation item extracted from source code.
41. #[derive(Debug, Clone, Serialize, Deserialize)]
42. pub struct DocItem {
43.     /// Item name.
44.     pub name: String,
45.     /// Item kind (function, class, interface, etc.).
46.     pub kind: DocItemKind,
47.     /// Documentation comment (JSDoc).
48.     pub doc: Option<String>,
49.     /// Source file path.
50.     pub source_path: String,
51.     /// Line number in source.
52.     pub line: u32,
53.     /// End line number in source.
54.     pub end_line: u32,
55.     /// Column number in source.
56.     pub column: u32,
57.     /// Raw JSDoc comment content without the outer delimiters.
58.     pub jsdoc: Option<String>,
59.     /// Whether the item is exported.
60.     pub exported: bool,
61.     /// Type signature (if applicable).
62.     pub signature: Option<String>,
63.     /// Parameters (for functions/methods).
64.     pub params: Vec<ParamDoc>,
65.     /// Return type (for functions/methods).
66.     pub return_type: Option<String>,
67.     /// Child items (for classes, modules, etc.).
68.     pub children: Vec<DocItem>,
69.     /// JSDoc tags.
70.     pub tags: Vec<DocTag>,
71. }
72. 
73. /// Parameter documentation.
74. #[derive(Debug, Clone, Serialize, Deserialize)]
75. pub struct ParamDoc {
76.     /// Parameter name.
77.     pub name: String,
78.     /// Parameter type.
79.     pub type_annotation: Option<String>,
80.     /// Whether the parameter is optional.
81.     pub optional: bool,
82.     /// Default value (if any).
83.     pub default_value: Option<String>,
84.     /// Description from JSDoc @param tag.
85.     pub description: Option<String>,
86. }
87. 
88. /// JSDoc tag.
89. #[derive(Debug, Clone, Serialize, Deserialize)]
90. pub struct DocTag {
91.     /// Tag name (e.g., "param", "returns", "example").
92.     pub tag: String,
93.     /// Tag value.
94.     pub value: String,
95.     /// JSDoc type annotation, when the tag has a `{type}` part.
96.     #[serde(default, skip_serializing_if = "Option::is_none")]
97.     pub type_annotation: Option<String>,
98.     /// JSDoc name, when the tag has a name part.
99.     #[serde(default, skip_serializing_if = "Option::is_none")]
100.     pub name: Option<String>,
101.     /// Whether the named part was marked optional.
102.     #[serde(default, skip_serializing_if = "Option::is_none")]
103.     pub optional: Option<bool>,
104.     /// Default value from `[name=value]` syntax.
105.     #[serde(default, skip_serializing_if = "Option::is_none")]
106.     pub default_value: Option<String>,
107.     /// Structured tag description parsed by `ox_jsdoc`.
108.     #[serde(default, skip_serializing_if = "Option::is_none")]
109.     pub description: Option<String>,
110. }
111. 
112. impl DocTag {
113.     fn new(tag: String, value: String) -> Self {
114.         Self {
115.             tag,
116.             value,
117.             type_annotation: None,
118.             name: None,
119.             optional: None,
120.             default_value: None,
121.             description: None,
122.         }
123.     }
124. }
125. 
126. #[derive(Debug, Clone)]
127. struct ParsedParamTag {
128.     name: String,
129.     type_annotation: Option<String>,
130.     optional: bool,
131.     default_value: Option<String>,
132.     description: Option<String>,
133. }
134. 
135. /// Kind of documentation item.
136. #[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
137. #[serde(rename_all = "lowercase")]
138. pub enum DocItemKind {
139.     /// Module or namespace.
140.     Module,
141.     /// Function.
142.     Function,
143.     /// Class.
144.     Class,
145.     /// Interface (TypeScript).
146.     Interface,
147.     /// Type alias.
148.     Type,
149.     /// Enum.
150.     Enum,
151.     /// Variable or constant.
152.     Variable,
153.     /// Class method.
154.     Method,
155.     /// Class property.
156.     Property,
157.     /// Constructor.
158.     Constructor,
159.     /// Getter.
160.     Getter,
161.     /// Setter.
162.     Setter,
163. }
164. 
165. /// Documentation extractor.
166. pub struct DocExtractor {
167.     /// Include private items.
168.     include_private: bool,
169. }
170. 
171. impl DocExtractor {
172.     /// Creates a new documentation extractor.
173.     #[must_use]
174.     pub fn new() -> Self {
175.         Self { include_private: false }
176.     }
177. 
178.     /// Creates a new extractor that includes private items.
179.     #[must_use]
180.     pub fn with_private(include_private: bool) -> Self {
181.         Self { include_private }
182.     }
183. 
184.     /// Extracts documentation from a source file.
185.     pub fn extract_file(&self, path: &Path) -> ExtractResult<Vec<DocItem>> {
186.         let extension = path.extension().and_then(|e| e.to_str()).unwrap_or("");
187. 
188.         match extension {
189.             "ts" | "tsx" | "js" | "jsx" | "mts" | "mjs" | "cts" | "cjs" => self.extract_js_ts(path),
190.             _ => Err(ExtractError::UnsupportedFile(extension.to_string())),
191.         }
192.     }
193. 
194.     /// Extracts documentation from source code string.
195.     pub fn extract_source(
196.         &self,
197.         source: &str,
198.         file_path: &str,
199.         source_type: SourceType,
200.     ) -> ExtractResult<Vec<DocItem>> {
201.         let allocator = Allocator::default();
202.         let ret = Parser::new(&allocator, source, source_type).parse();
203. 
204.         if !ret.errors.is_empty() {
205.             let error_msg = ret
206.                 .errors
207.                 .iter()
208.                 .map(std::string::ToString::to_string)
209.                 .collect::<Vec<_>>()
210.                 .join(", ");
211.             return Err(ExtractError::Parse(error_msg));
212.         }
213. 
214.         let comments: Vec<Comment> = ret.program.comments.iter().copied().collect();
215.         let jsdoc_cache = build_jsdoc_cache(source, &comments);
216. 
217.         let mut visitor = DocVisitor::new(source, file_path, self.include_private, jsdoc_cache);
218.         visitor.visit_program(&ret.program);
219. 
220.         Ok(visitor.items)
221.     }
222. 
223.     /// Extracts documentation from a JavaScript/TypeScript file.
224.     fn extract_js_ts(&self, path: &Path) -> ExtractResult<Vec<DocItem>> {
225.         let content = std::fs::read_to_string(path)?;
226.         let file_path = path.to_string_lossy().to_string();
227.         let source_type = SourceType::from_path(path).unwrap_or_default();
228. 
229.         self.extract_source(&content, &file_path, source_type)
230.     }
231. }
232. 
233. impl Default for DocExtractor {
234.     fn default() -> Self {
235.         Self::new()
236.     }
237. }
238. 
239. /// Pre-parsed JSDoc data for one comment: `(raw, description, tags)`.
240. type ParsedJsdoc = (String, String, Vec<DocTag>);
241. 
242. /// Extract the JSDoc content body from a comment with a single allocation.
243. fn extract_raw_jsdoc(comment: &Comment, source: &str) -> String {
244.     let content = comment.content_span().source_text(source);
245.     let trimmed = content.strip_prefix('*').unwrap_or(content);
246.     trimmed.trim_matches('\n').to_string()
247. }
248. 
249. /// Pre-parse every JSDoc comment in the program with a single batch call so the
250. /// AST visitor can resolve documentation by `attached_to` via a cheap lookup.
251. fn build_jsdoc_cache(source: &str, comments: &[Comment]) -> FxHashMap<u32, ParsedJsdoc> {
252.     let jsdoc_comments: Vec<&Comment> =
253.         comments.iter().filter(|comment| comment.is_jsdoc()).collect();
254.     if jsdoc_comments.is_empty() {
255.         return FxHashMap::default();
256.     }
257. 
258.     let items: Vec<JsdocBatchItem<'_>> = jsdoc_comments
259.         .iter()
260.         .map(|comment| JsdocBatchItem {
261.             source_text: comment.span.source_text(source),
262.             base_offset: comment.span.start,
263.         })
264.         .collect();
265. 
266.     let options = JsdocParseOptions { preserve_whitespace: true, ..JsdocParseOptions::default() };
267.     let result = parse_jsdoc_batch_to_bytes(&items, options);
268. 
269.     let failed: FxHashSet<u32> =
270.         result.diagnostics.iter().map(|diagnostic| diagnostic.root_index).collect();
271. 
272.     let mut cache: FxHashMap<u32, ParsedJsdoc> =
273.         FxHashMap::with_capacity_and_hasher(jsdoc_comments.len(), FxBuildHasher);
274. 
275.     if let Ok(source_file) =
276.         ox_jsdoc::decoder::source_file::LazySourceFile::new(&result.binary_bytes)
277.     {
278.         for (index, (comment, root)) in jsdoc_comments.iter().zip(source_file.asts()).enumerate() {
279.             let raw = extract_raw_jsdoc(comment, source);
280.             let (doc, tags) = match root {
281.                 Some(root) if !failed.contains(&(index as u32)) => {
282.                     let doc = root
283.                         .description_text(false)
284.                         .map_or_else(String::new, |description| description.trim().to_string());
285.                     let tags = root.tags().map(DocVisitor::convert_jsdoc_tag).collect();
286.                     (doc, tags)
287.                 }
288.                 _ => DocVisitor::parse_jsdoc_fallback(&raw),
289.             };
290.             cache.insert(comment.attached_to, (raw, doc, tags));
291.         }
292.     } else {
293.         for comment in &jsdoc_comments {
294.             let raw = extract_raw_jsdoc(comment, source);
295.             let (doc, tags) = DocVisitor::parse_jsdoc_fallback(&raw);
296.             cache.insert(comment.attached_to, (raw, doc, tags));
297.         }
298.     }
299. 
300.     cache
301. }
302. 
303. /// AST visitor for extracting documentation.
304. struct DocVisitor<'a> {
305.     source: &'a str,
306.     file_path: &'a str,
307.     include_private: bool,
308.     jsdoc_cache: FxHashMap<u32, ParsedJsdoc>,
309.     line_starts: Vec<usize>,
310.     items: Vec<DocItem>,
311.     /// Track default export
312.     has_default_export: bool,
313. }
314. 
315. impl<'a> DocVisitor<'a> {
316.     fn new(
317.         source: &'a str,
318.         file_path: &'a str,
319.         include_private: bool,
320.         jsdoc_cache: FxHashMap<u32, ParsedJsdoc>,
321.     ) -> Self {
322.         let mut line_starts = vec![0];
323.         line_starts.extend(
324.             source
325.                 .bytes()
326.                 .enumerate()
327.                 .filter_map(|(index, byte)| (byte == b'\n').then_some(index + 1)),
328.         );
329. 
330.         Self {
331.             source,
332.             file_path,
333.             include_private,
334.             jsdoc_cache,
335.             line_starts,
336.             items: Vec::new(),
337.             has_default_export: false,
338.         }
339.     }
340. 
341.     fn slice(&self, start: u32, end: u32) -> String {
342.         self.source[start as usize..end as usize].to_string()
343.     }
344. 
345.     fn line_number(&self, position: u32) -> u32 {
346.         let position = position as usize;
347.         self.line_starts.partition_point(|&start| start <= position) as u32
348.     }
349. 
350.     fn column_number(&self, position: u32) -> u32 {
351.         let position = position as usize;
352.         let line_index = self.line_starts.partition_point(|&start| start <= position);
353.         let line_start = self.line_starts[line_index.saturating_sub(1)];
354.         (position.saturating_sub(line_start)) as u32
355.     }
356. 
357.     fn span_lines(&self, start: u32, end: u32) -> (u32, u32) {
358.         let start_line = self.line_number(start);
359.         let end_position = end.saturating_sub(1).max(start);
360.         let end_line = self.line_number(end_position);
361.         (start_line, end_line)
362.     }
363. 
364.     fn extract_jsdoc(&self, attached_to: u32) -> Option<(String, String, Vec<DocTag>)> {
365.         self.jsdoc_cache.get(&attached_to).cloned()
366.     }
367. 
368.     fn convert_jsdoc_tag(tag: LazyJsdocTag<'_>) -> DocTag {
369.         let tag_name = tag.tag().value().to_string();
370.         let value = Self::format_jsdoc_tag_value(&tag_name, &tag);
371.         let type_annotation = tag
372.             .raw_type()
373.             .map(|raw_type| raw_type.raw().trim().to_string())
374.             .filter(|value| !value.is_empty());
375.         let name =
376.             tag.name().map(|name| name.raw().trim().to_string()).filter(|value| !value.is_empty());
377.         let optional = name.as_ref().map(|_| tag.optional());
378.         let default_value = tag.default_value().map(str::trim).filter(|value| !value.is_empty());
379.         let description =
380.             Self::format_structured_tag_description(&tag_name, &tag, type_annotation.as_deref());
381. 
382.         DocTag {
383.             tag: tag_name,
384.             value,
385.             type_annotation,
386.             name,
387.             optional,
388.             default_value: default_value.map(str::to_string),
389.             description,
390.         }
391.     }
392. 
393.     fn format_structured_tag_description(
394.         tag_name: &str,
395.         tag: &LazyJsdocTag<'_>,
396.         type_annotation: Option<&str>,
397.     ) -> Option<String> {
398.         if matches!(tag_name, "returns" | "return") {
399.             let raw_body = tag.raw_body().map(str::trim).filter(|value| !value.is_empty())?;
400.             let without_type = type_annotation
401.                 .and_then(|type_annotation| {
402.                     raw_body.strip_prefix(&format!("{{{type_annotation}}}")).map(str::trim_start)
403.                 })
404.                 .unwrap_or(raw_body);
405.             return Self::clean_tag_description(without_type);
406.         }
407. 
408.         tag.description().and_then(Self::clean_tag_description)
409.     }
410. 
411.     fn format_jsdoc_tag_value(tag_name: &str, tag: &LazyJsdocTag<'_>) -> String {
412.         if !matches!(tag_name, "param" | "arg" | "argument") {
413.             if let Some(raw_body) = tag.raw_body().map(str::trim).filter(|value| !value.is_empty())
414.             {
415.                 return raw_body.to_string();
416.             }
417.         }
418. 
419.         let mut parts = Vec::new();
420. 
421.         if let Some(raw_type) = tag.raw_type() {
422.             let raw_type = raw_type.raw().trim();
423.             if !raw_type.is_empty() {
424.                 parts.push(format!("{{{raw_type}}}"));
425.             }
426.         }
427. 
428.         if let Some(name) = tag.name() {
429.             let name = name.raw().trim();
430.             if !name.is_empty() {
431.                 let name = if tag.optional() {
432.                     tag.default_value().map_or_else(
433.                         || format!("[{name}]"),
434.                         |default_value| format!("[{name}={default_value}]"),
435.                     )
436.                 } else {
437.                     name.to_string()
438.                 };
439.                 parts.push(name);
440.             }
441.         }
442. 
443.         if let Some(description) =
444.             tag.description().map(str::trim).filter(|value| !value.is_empty())
445.         {
446.             if parts.is_empty() {
447.                 parts.push(description.to_string());
448.             } else {
449.                 parts.push(format!("- {description}"));
450.             }
451.         }
452. 
453.         if !parts.is_empty() {
454.             return parts.join(" ");
455.         }
456. 
457.         if let Some(raw_body) = tag.raw_body().map(str::trim).filter(|value| !value.is_empty()) {
458.             return raw_body.to_string();
459.         }
460. 
461.         tag.body().map_or_else(String::new, |body| match body {
462.             LazyJsdocTagBody::Generic(body) => body.description().unwrap_or_default().to_string(),
463.             LazyJsdocTagBody::Raw(body) => body.raw().to_string(),
464.             LazyJsdocTagBody::Borrows(_) => String::new(),
465.         })
466.     }
467. 
468.     /// Fallback parser used when the external JSDoc parser cannot produce a root.
469.     fn parse_jsdoc_fallback(comment: &str) -> (String, Vec<DocTag>) {
470.         let mut description_lines = Vec::new();
471.         let mut tags = Vec::new();
472.         let mut current_tag: Option<(String, Vec<String>)> = None;
473. 
474.         let lines: Vec<String> = comment
475.             .lines()
476.             .map(|line| {
477.                 let trimmed = line.trim_start();
478.                 let trimmed = trimmed.strip_prefix('*').unwrap_or(trimmed);
479.                 trimmed.strip_prefix(' ').unwrap_or(trimmed).trim_end().to_string()
480.             })
481.             .collect();
482. 
483.         for line in lines {
484.             let trimmed = line.trim_start();
485.             if let Some(without_at) = trimmed.strip_prefix('@') {
486.                 // Save previous tag if any
487.                 if let Some((tag, value_lines)) = current_tag.take() {
488.                     tags.push(DocTag::new(tag, value_lines.join("\n").trim().to_string()));
489.                 }
490. 
491.                 let split_at = without_at
492.                     .char_indices()
493.                     .find_map(|(index, ch)| ch.is_whitespace().then_some(index))
494.                     .unwrap_or(without_at.len());
495.                 let tag_name = without_at[..split_at].to_string();
496.                 let tag_value = without_at[split_at..].trim_start().to_string();
497.                 current_tag = Some((tag_name, vec![tag_value]));
498.             } else if let Some((_, ref mut value_lines)) = current_tag {
499.                 value_lines.push(line);
500.             } else {
501.                 description_lines.push(line);
502.             }
503.         }
504. 
505.         // Save last tag if any
506.         if let Some((tag, value_lines)) = current_tag {
507.             tags.push(DocTag::new(tag, value_lines.join("\n").trim().to_string()));
508.         }
509. 
510.         (description_lines.join("\n").trim().to_string(), tags)
511.     }
