606.     fn format_class_signature(&self, class: &Class, name: &str, exported: bool) -> String {
607.         let mut sig = String::new();
608.         if exported {
609.             sig.push_str("export ");
610.         }
611.         if class.r#abstract {
612.             sig.push_str("abstract ");
613.         }
614.         if class.declare {
615.             sig.push_str("declare ");
616.         }
617.         sig.push_str("class ");
618.         sig.push_str(name);
619.         sig.push_str(&self.format_type_parameter_declaration(class.type_parameters.as_ref()));
620. 
621.         if let Some(super_class) = &class.super_class {
622.             sig.push_str(" extends ");
623.             sig.push_str(&self.slice(super_class.span().start, super_class.span().end));
624.             if let Some(type_params) = &class.super_type_arguments {
625.                 sig.push_str(&self.format_type_parameter_declaration(Some(type_params)));
626.             }
627.         }
628. 
629.         let implements = &class.implements;
630.         if !implements.is_empty() {
631.             let implements_str = implements
632.                 .iter()
633.                 .map(|item| {
634.                     let mut value =
635.                         self.slice(item.expression.span().start, item.expression.span().end);
636.                     if let Some(type_params) = &item.type_parameters {
637.                         value.push_str(&self.format_type_parameter_declaration(Some(type_params)));
638.                     }
639.                     value
640.                 })
641.                 .collect::<Vec<_>>()
642.                 .join(", ");
643. 
644.             if !implements_str.is_empty() {
645.                 sig.push_str(" implements ");
646.                 sig.push_str(&implements_str);
647.             }
648.         }
649. 
650.         sig
651.     }
