844.     fn binding_pattern_name(pattern: &oxc_ast::ast::BindingPattern) -> String {
845.         match &pattern.kind {
846.             BindingPatternKind::BindingIdentifier(id) => id.name.to_string(),
847.             BindingPatternKind::AssignmentPattern(assign) => {
848.                 Self::binding_pattern_name(&assign.left)
849.             }
850.             BindingPatternKind::ObjectPattern(_) => "param".to_string(),
851.             BindingPatternKind::ArrayPattern(_) => "param".to_string(),
852.         }
853.     }
