855.     fn binding_pattern_default_value(
856.         &self,
857.         pattern: &oxc_ast::ast::BindingPattern,
858.     ) -> Option<String> {
859.         match &pattern.kind {
860.             BindingPatternKind::AssignmentPattern(assign) => {
861.                 Some(self.slice(assign.right.span().start, assign.right.span().end))
862.             }
863.             _ => None,
864.         }
865.     }
