889.     /// Format a TypeScript type.
890.     fn format_ts_type(&self, ts_type: &TSType) -> String {
891.         match ts_type {
892.             TSType::TSAnyKeyword(_) => "any".to_string(),
893.             TSType::TSBooleanKeyword(_) => "boolean".to_string(),
894.             TSType::TSNumberKeyword(_) => "number".to_string(),
895.             TSType::TSStringKeyword(_) => "string".to_string(),
896.             TSType::TSVoidKeyword(_) => "void".to_string(),
897.             TSType::TSNullKeyword(_) => "null".to_string(),
898.             TSType::TSUndefinedKeyword(_) => "undefined".to_string(),
899.             TSType::TSNeverKeyword(_) => "never".to_string(),
900.             TSType::TSBigIntKeyword(_) => "bigint".to_string(),
901.             TSType::TSSymbolKeyword(_) => "symbol".to_string(),
902.             TSType::TSObjectKeyword(_) => "object".to_string(),
903.             TSType::TSTypeReference(ref_type) => Self::format_ts_type_name(&ref_type.type_name),
904.             TSType::TSArrayType(arr) => format!("{}[]", self.format_ts_type(&arr.element_type)),
905.             TSType::TSUnionType(union) => {
906.                 let types: Vec<String> =
907.                     union.types.iter().map(|t| self.format_ts_type(t)).collect();
908.                 types.join(" | ")
909.             }
910.             TSType::TSIntersectionType(inter) => {
911.                 let types: Vec<String> =
912.                     inter.types.iter().map(|t| self.format_ts_type(t)).collect();
913.                 types.join(" & ")
914.             }
915.             TSType::TSFunctionType(func) => {
916.                 let params: Vec<String> = func
917.                     .params
918.                     .items
919.                     .iter()
920.                     .map(|p| self.format_binding_pattern(&p.pattern))
921.                     .collect();
922.                 let ret = self.format_ts_type(&func.return_type.type_annotation);
923.                 format!("({}) => {}", params.join(", "), ret)
924.             }
925.             TSType::TSTypeLiteral(_) => "{ ... }".to_string(),
926.             TSType::TSTupleType(tuple) => {
927.                 let types: Vec<String> = tuple
928.                     .element_types
929.                     .iter()
930.                     .map(|t| self.format_ts_type(t.to_ts_type()))
931.                     .collect();
932.                 format!("[{}]", types.join(", "))
933.             }
934.             TSType::TSLiteralType(lit) => match &lit.literal {
935.                 oxc_ast::ast::TSLiteral::StringLiteral(s) => format!("\"{}\"", s.value),
936.                 oxc_ast::ast::TSLiteral::NumericLiteral(n) => n
937.                     .raw
938.                     .as_ref()
939.                     .map_or_else(|| n.value.to_string(), std::string::ToString::to_string),
940.                 oxc_ast::ast::TSLiteral::BooleanLiteral(b) => b.value.to_string(),
941.                 _ => "literal".to_string(),
942.             },
943.             _ => "unknown".to_string(),
944.         }
945.     }
946. 
947.     /// Format a TypeScript type name.
948.     fn format_ts_type_name(name: &TSTypeName) -> String {
949.         match name {
950.             TSTypeName::IdentifierReference(id) => id.name.to_string(),
951.             TSTypeName::QualifiedName(qn) => {
952.                 format!("{}.{}", Self::format_ts_type_name(&qn.left), qn.right.name)
953.             }
954.         }
955.     }
