def is_test(p):
    base=p.split('/')[-1].lower(); parts=set(p.lower().split('/'))
    return any(x in parts for x in ['test','tests','__tests__','spec','e2e','integration']) or re.search(r'(test|spec|e2e|it)\.(js|jsx|ts|tsx|mjs|cjs|py|go|rs)$', base) or re.match(r'test_.*\.py$',base) or base.endswith('_test.go')

def is_doc_ci(p):
